quests[63605] = { id = 63605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauroliskenseele", description = "<Die Sauroliskenseele ist flink und klug. Ihr könnt jetzt die Gestalt des Saurolisken nutzen.>", sourceObjective = "Bringt die Sauroliskenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Saurolisk. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63606] = { id = 63606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinnenseele", description = "<Die Spinnenseele ist gelenkig und gerissen. Ihr könnt jetzt die Gestalt der Spinne nutzen.>", sourceObjective = "Bringt die Spinnenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, die Spinne. Ihr könnt ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63607] = { id = 63607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorhornseele", description = "<Die Terrorhornseele ist brutal und beharrlich. Ihr könnt jetzt die Gestalt des Terrorhorns nutzen.>", sourceObjective = "Bringt die Terrorhornseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, das Terrorhorn. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63608] = { id = 63608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flusspferdseele", description = "<Die Flusspferdseele ist wild. Ihr könnt jetzt die Gestalt des Flusspferds nutzen.>", sourceObjective = "Bringt die Flusspferdseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, das Flusspferd. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63609] = { id = 63609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kodoseele", description = "<Die Kodoseele ist ruhig und treu. Ihr könnt jetzt die Gestalt des Kodo nutzen.>", sourceObjective = "Bringt die Kodoseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Kodo. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63610] = { id = 63610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mammutseele", description = "<Die Mammutseele ist mutig und hat einen ausgeprägten Beschützerinstinkt. Ihr könnt jetzt die Gestalt des Mammuts nutzen.>", sourceObjective = "Bringt die Mammutseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, das Mammut. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63611] = { id = 63611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rune Chest Opened" }
quests[63612] = { id = 63612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befehlsketten", description = "Wenn wir schon eine Stellung so nahe an den Gebieten des Kerkermeisters halten müssen, dann nicht ohne eine Absicherung.\n\nVyraz und Helya haben sich hinter die Mauern von Desmotaeron zurückgezogen. Sie sind in ihrer vermeintlichen Sicherheit nachlässig geworden, was uns eine Gelegenheit verschafft.\n\nWir werden sie überrumpeln. Schlagt schnell und gnadenlos zu, vielleicht können wir diesen Schlangen dann die Köpfe abschlagen.", sourceObjective = "Trefft Draka in der Nähe von Desmotaeron.", completion = "Noch haben sie uns nicht bemerkt. Das wird nicht lange so bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63613] = { id = 63613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tore der Verdammten", description = "Wir müssen uns auf den Angriff vorbereiten, bevor wir der Zerekriss ein Signal geben. Sobald sie in Position ist, werden unsere Verbündeten Schwarze Tore benutzen, um das Gebiet anzugreifen.\n\nWir müssen die Schwarzen Tore auf dieser Seite beschwören. Findet strategisch geeignete Orte für sie.", sourceObjective = "Beschwört 4 Schwarze Tore.", progress = "Sobald wir alle Schwarzen Tore beschworen haben, kann der eigentliche Kampf beginnen.", completion = "Das sollte ausreichen, um den Großteil der Armee durchzuschicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[63614] = { id = 63614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Waffe in der Hand", description = "Einen Augenblick bitte, {name}.\n\nIch habe meine Axt Dra'gora verloren, als ich sie bei unserem ersten Treffen im Schlund nach Helya warf, und ich habe sie seitdem nicht mehr gesehen. Wenn Helya wirklich an diesem Ort ihre Truppen befehligt, dann wird meine Axt vielleicht dort aufbewahrt.\n\nIch habe diese Axt in Nagrand gefertigt und sie erinnert mich an gute Zeiten an der Seite meiner Familie. Ich möchte ihr Gewicht wieder in meinen Händen spüren.", sourceObjective = "Findet Dra'gora, Thralls Axt.", progress = "In der Hitze des Gefechts habe ich meine Axt geschleudert...", completion = "Ich danke Euch, {name}. Ich hatte schon befürchtet, ich hätte meine Axt für immer verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63615] = { id = 63615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flügel stutzen", description = "Der Himmel wird von Helyas kyrianischen Anhängern geradezu verdunkelt. Wenn wir ihre Zahl nicht ausdünnen, könnten die Zerekriss und unsere Verbündeten in der Luft Schwierigkeiten bei ihrem Vorstoß bekommen.\n\nIch habe bemerkt, dass die Schlundgebundenen oftmals magische Ketten benutzen. Wir könnten ihre Ausrüstung gegen sie wenden und sie vom Himmel herunterzerren.", sourceObjective = "Benutzt Ketten der Schlundgebundenen, um 6 helgebundene Seelenbrecher zu töten.", progress = "Wir müssen den Himmel freibekommen, bevor wir mit dem eigentlichen Angriff beginnen können.", completion = "Unsere Feinde werden lernen, dass selbst der Himmel nicht mehr sicher für sie ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63616] = { id = 63616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrekt ausgeführte Aufgabe", description = "Wir sind bereit, den Angriff zu starten.\n\nGebt der Zerekriss das Signal. Zeigen wir ihnen die Macht einer maldraxxischen Nekropole und der vereinten Armeen der Schattenlande!", sourceObjective = "Gebt der Zerekriss das Signal und startet den Angriff.", progress = "Nichts kann die Macht von Maldraxxus aufhalten!", completion = "Da ist unsere Lücke. Jetzt stoßen wir vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[63617] = { id = 63617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenbiegen", description = "In all dem Chaos hat jemand die Tore des oberen Festungsbereichs offen gelassen. Wenn wir durchschlüpfen, bemerken sie uns vielleicht erst, wenn es zu spät ist.\n\nEiner von Helyas Leutnants steht zwischen uns und Burg Helgarde. Macht kurzen Prozess mit ihm.", sourceObjective = "Tötet Eisenhüter Salryx.", progress = "Wir müssen durch dieses Tor durch.", completion = "Und jetzt werden wir Chaos säen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63618] = { id = 63618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Maldraxxus am besten kann", description = "Jeder Feind, den wir hier besiegen, ist einer, mit dem sich unsere Armee nicht weiter auseinandersetzen muss. Wir werden dafür sorgen, dass sie die wahre Bestimmung von Maldraxxus nicht so schnell vergessen werden. Zeigt ihnen, was mit jenen passiert, die wir als Bedrohung für die Schattenlande ansehen.\n\nTötet jeden Schlundgebundenen in Sichtweite.", sourceObjective = "Tötet 10 Schlundgebundene in der Festung Desmotaeron.", progress = "Jeder Schlundgebundene, den wir ausschalten, ist eine Bedrohung weniger für unsere Kräfte in Korthia.", completion = "Sie waren verrückt zu glauben, dass sie mit uns die Klingen kreuzen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63619] = { id = 63619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschmäht und vergessen", description = "Wartet... Ich kenne Euch! <Der Schlundgänger/Die Schlundgängerin>!\n\nMeine Brüder und Schwestern wurden beeinflusst... verdorben. Einige haben bereitwillig die Macht von Helya entgegengenommen, aber andere konnten ihr widerstehen. Wir alle sind jetzt ihrer Macht unterworfen.\n\nIch bin geflohen, als die Kämpfe begannen, aber die meisten der verbliebenen Verschmähten werden schrecklichen Ritualen unterzogen.\n\nIch bitte Euch, sie zu befreien. Wir kehren dann zur Bastion zurück und unterwerfen uns dem Urteil der Archon.", sourceObjective = "Befreit 5 Gefangene der Verschmähten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63620] = { id = 63620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schuld eines Verräters", description = "Seit er uns verraten hat, ist Vyraz eine konstante Bedrohung für Maldraxxus. Als Baronin des Hauses der Auserwählten ist es meine Pflicht, diese Bedrohung zu beseitigen und den Mord an Markgraf Krexus zu rächen.\n\nWie der Primus sagte: Wir müssen dieser Schlange den Kopf abschlagen.\n\nJetzt ist die Zeit gekommen, um genau das zu tun!", sourceObjective = "Tötet Vyraz.", completion = "<Draka spuckt auf den Leichnam von Vyraz.>\n\nUnd mit dem Ende dieses Verräters wird Maldraxxus wieder vereint sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[63621] = { id = 63621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kettenrasseln", description = "Sie nennen ihn den Hüter der Ketten. Unterschätzt seine Macht nicht. Er hat Seelen in der Nähe gebunden, um einen Angriff auf unsere Stellung vorzubereiten.\n\nIch will, dass Ihr diese Bedrohung beseitigt, <Schlundgänger/Schlundgängerin>, bevor sie unsere Truppen in Gefahr bringt.", sourceObjective = "Eliminiert den Hüter der Ketten.", completion = "Ich wusste, dass wir uns auf Euch verlassen können, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63622] = { id = 63622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in unserem Namen", description = "Helya und Vyraz sind erledigt. Damit haben wir heute einen entscheidenden Sieg gegen die Schlundgebundenen erzielt. Wir haben auch gezeigt, wozu die verbündeten Kräfte der Schattenlande imstande sind.\n\nWir sollten nach Korthia zurückkehren, bevor noch etwas geschieht.", sourceObjective = "Kehrt zum Primus in Korthia zurück.", progress = "Wir haben den Truppen des Kerkermeisters einen Schlag verpasst. Nehmt Euch Zeit, um Euch vor dem nächsten Angriff auszuruhen.", completion = "Es besteht kein Zweifel, dass wir erneut Druck auf Desmotaeron ausüben müssen.\n\nDie Hexe der Val'kyr wird alles dafür tun, uns nicht entkommen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63623] = { id = 63623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen leeren Thron ausfüllen", description = "<Schlundgänger/Schlundgängerin>.\n\nIn meiner langen Abwesenheit habt Ihr dem Pakt der Nekrolords Ordnung und Stärke zurückgegeben. Als Anerkennung lade ich Euch ein, einer Zeremonie beizuwohnen.\n\nKehrt mit mir zu meinem Machtsitz in Maldraxxus zurück. Es ist an der Zeit, dass ich ein Individuum belohne, das unserer Sache äußerst treu gedient hat.", sourceObjective = "Kehrt zum Sitz des Primus zurück.", completion = "Dies ist der erste Schritt in Richtung der Wiederherstellung von Maldraxxus.", sourceObjectiveStatus = "unverified-source-field" }
quests[63624] = { id = 63624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wege, die wir beschreiten", description = "Die Armeen von Maldraxxus sind stark. Sie werden sich von Vyraz' Missetat erholen.\n\nAls Erstes müssen wir alles wieder aufbauen. <Schlundgänger/Schlundgängerin>, werdet <Zeuge/Zeugin> einer neuen Ära von Maldraxxus!", sourceObjective = "Wohnt Drakas Aufstiegszeremonie bei.", completion = "Wir müssen alle nach vorn blicken. Die Schattenlande verlassen sich auf unsere Stärke.", sourceObjectiveStatus = "unverified-source-field" }
quests[63625] = { id = 63625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier ist eine Axt. An die Arbeit!", description = "Unsere Truppen stoßen auf heftigen Widerstand! <Schlundgänger/Schlundgängerin>, greift Euch eine Waffe und zieht in den Kampf!\n\nBeseitigt die Verteidigung dieser Tore: die Truppen der Schlundgebundenen und ihren Kommandanten.", sourceObjective = "Eliminiert 15 Truppen der Schlundgebundenen und Kommandant Mallamort.", completion = "Der Sieg wird unser sein, Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[63638] = { id = 63638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht den Rücken zuwenden", description = "Damit wären wir Sylvanas und ihre Schlundgebundenen los... zumindest vorerst.\n\nAber wir müssen uns beeilen und dafür sorgen, dass die Königin und ihr Siegel in Sicherheit sind!\n\nDie Winterkönigin war gleich außerhalb des Herzens des Waldes, um die gestohlenen Wildsamen vor dem Schlund zu schützen.", sourceObjective = "Seht nach der Winterkönigin.", progress = "Der Wald antwortet.", completion = "Der Ardenwald hängt von seinem Zyklus ab. Was für einen Sinn gäbe es ohne diese Geister?\n\nIch konnte nicht zulassen, dass die Truppen des Kerkermeisters zerstören, was wir in harten Kämpfen beschützt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63639] = { id = 63639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht in Oribos", description = "Der Ardenwald hat der gnadenlosen Kraft des Schlunds widerstanden.\n\nAber das hat dennoch nicht gereicht.\n\nKehrt zu unseren Verbündeten in Oribos zurück. Dieser Verlust muss vergolten und Maßnahmen müssen ergriffen werden.", sourceObjective = "Kehrt zu Tal-Inara in Oribos zurück.", completion = "Der Kerkermeister hat seinen Angriff auf Oribos begonnen.\n\nMeine größten Befürchtungen haben sich bewahrheitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[63644] = { id = 63644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Nachrichten", description = "Die Bedrohung, die die Nathrezim für unsere Streitkräfte darstellen, darf nicht unterschätzt werden. Sie sind gerissen, selbst im Vergleich mit den besten Veteranen des Hauses der Augen, und wir kennen ihren ganzen Plan nicht.\n\nUnter den Venthyr gibt es eine, die die Nathrezim mit ihrem Zorn viele Jahrtausende lang aus den Schattenlanden vertrieben hat.\n\nIch bitte Euch, nach Sündensturz zu reisen, um Prinz Renathal aufzusuchen und ihm dieses Schreiben zu überbringen. Ich werde einen meiner eigenen Spione, die Baronin Vashj, schicken, um Euch dort zu treffen. Macht Euch ihre Erfahrung mit den Nathrezim zunutze.", sourceObjective = "Sprecht mit Prinz Renathal bei Morgenfels in Revendreth.", progress = "Wahrhaft finstere Nachrichten.", completion = "Die Nathrezim sind zurück? Ich hätte nie gedacht, dass sie jemals wieder so dreist werden würden.\n\nEine Schande, dass sie in ihrem Exil nichts gelernt haben und nun als Feinde statt als Familie zu uns zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63645] = { id = 63645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangener von Morgenfels", description = "Oh, Ihr habt es offensichtlich noch nicht gehört.\n\nWir haben ihn. Graf Denathrius, Meister von Revendreth, Gefangener seiner eigenen Klinge.\n\nWir haben ihn im Zuge eines unserer letzten Schlachtzüge gegen Schloss Nathria überwältigen können.\n\nEs bedurfte einer Armee von unvergleichlicher Tapferkeit und Vorbereitung. Es bedurfte Geschick und Vermögen. Es bedurfte eines Wunders.\n\nUnd so wird der Erlöser erlöst werden. Möchtet Ihr mehr darüber erfahren?", sourceObjective = "Erfahrt von Prinz Renathal mehr über das Schicksal von Graf Denathrius.", completion = "Es wird vielleicht Ewigkeiten brauchen, aber wir werden Denathrius an seine Bestimmung und daran erinnern, wie er sein Handwerk wieder in aller Pracht ausführen kann.\n\nDas Licht an diesem Ort ist mächtig. Nur wenige Venthyr können eine solche Macht lange ertragen, ohne ihr zu erliegen. Ein passender Ort, um zu lehren, ohne gestört zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[63646] = { id = 63646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konvoi der Pakte", description = "Ein neues Siegel der Venthyr ließe sich nur mit allen sieben Medaillons schmieden.\n\nDer Primus hatte recht. Die Person, die wir brauchen, ist die Steinhauerin. Mit ihren Anschuldigungen gegen die Ungesehenen ließe sich eine ganze Bibliothek füllen, und sie besitzt das letzte Medaillon, das wir benötigen. Ich glaube, es ist längst überfällig, dass wir beide sie für unsere Sache gewinnen.\n\nIch werde die Vorbereitungen treffen. Wir werden es dieses Mal richtig machen, mit Geschenken und Diplomatie.\n\nIhr solltet Chelra vorwarnen, sie wird eine Eskorte aufstellen wollen.", sourceObjective = "Versammelt die Gesandten und reitet zum Tor der Dominanz.", progress = "Was bringt Ihr mir, Schlundgänger? Seid gewarnt, ich habe für Täuschungen kein Verständnis und bin mir nicht zu schade, Boten an die Gargons zu verfüttern.", completion = "Hmm... Ein Brief vom Primus persönlich? Ich hatte mich schon gefragt, was aus dem alten Tyrannen wohl geworden ist.\n\n<Sie überfliegt den Brief.>\n\nAha... Ich verstehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[63647] = { id = 63647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ungesehenen Gäste", description = "Schreckenslords.\n\nNatürlich. Natürlich kommen sie ausgerechnet jetzt zurück. Ich hatte schon fast geahnt, dass sie während der Dürre zurückkehren würden.\n\nAls ich Euch das erste Mal sah, war ich nicht ganz sicher, ob Ihr nicht zu ihnen gehört. Sie sind in den Zeitaltern, seit sie aus Revendreth geflohen sind, immer gerissener geworden.\n\nAber nicht gerissen genug... sollte ich meinen.\n\nKommt, <Schlundgänger/Schlundgängerin>. Folgt mir und macht kein Aufhebens. Haltet Eure Waffe bereit. Die Abgesandte, die Ihr mitgebracht habt, ist nicht ganz so loyal, wie Ihr vielleicht gedacht habt.", sourceObjective = "Unterstützt die Steinhauerin bei ihren Nachforschungen zur Gesandten.", completion = "Chelra war von Anfang an eine Nathrezim? Seit wir uns kannten?\n\nSelbst im Tod muss ich mich noch mit den Machenschaften der Nathrezim herumschlagen. Durch meine Sühne bin ich wohl zu vertrauensselig geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[63648] = { id = 63648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nal'ragas", description = "Das Medaillon der Steinhauerin darf nicht in den Händen der Nathrezim verbleiben.\n\nNach dem, was die Anklägerin zu unserer Mission erläutert hat, brauchen wir das Medaillon, um ein neues Siegel für die Venthyr zu schmieden. Zweifellos haben Nal'ragas und ihre Schergen auch genau deswegen gerade jetzt aus dem Hinterhalt zugeschlagen.\n\nDie Magie dieser Medaillons ist nicht gerade subtil und sie lassen sich in diesem Reich sehr leicht aufspüren. Wir sollten diese Nal'ragas verfolgen und beseitigen, bevor sie Verstärkung erhält.", sourceObjective = "Findet und besiegt Nal'ragas.", completion = "Ich habe mit der Steinhauerin gesprochen. Chelra fiel dem Meister zum Opfer, als ich Gefangener des Schlunds war.\n\nSie war über unzählige Zeitalter meine Freundin und Beschützerin, und ich wusste nicht einmal, dass sie ermordet und ihre Identität gestohlen worden war.\n\nEine weitere Sünde, für die Denathrius büßen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[63649] = { id = 63649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spion gegen Spion", description = "Nathrezim. Schreckenslords. Die Ungesehenen Gäste.\n\nNennt sie, wie Ihr wollt. Vor langer Zeit wurde dieses Volk nur aus dem einem Grund erschaffen, um als die wohl besten Spione und Infiltratoren zu dienen.\n\nDiese Eindringlinge haben drei Faktoren schwer unterschätzt: Kael'thas Sonnenwanderer, Baronin Vashj und {name}!\n\nIch habe ein Werkzeug mitgebracht, mit dessen Hilfe Kael'thas und ich Nathrezim aufgespürt und vernichtet haben, als wir unter Illidan dienten. Und ich bin die Herrin der Spione!\n\nKommt, lasst uns diese Eindringlinge jagen.", sourceObjective = "Findet und besiegt 5 Schreckenslordinfiltratoren.", progress = "Wer sagt denn, der Tod hätte keine kleinen Freuden zu bieten?", completion = "Die Venthyr sind selbstsicher geworden und wollten einfach nicht wahrhaben, dass die Nathrezim zurückkehren könnten. Und genau wegen dieser Blindheit hat der Verrat von Denathrius sie auch so getroffen.\n\nAb jetzt werden sie wohl wachsamer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63650] = { id = 63650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Infiltration", description = "Mal'Ganis.\n\nDieser Name ist mir seit Jahrhunderten nicht mehr über die Lippen gekommen. Und nun machen wir Jagd auf ihn.\n\nWenn er wirklich das Medaillon des Zorns bei sich trägt, kann er sich nirgends verstecken. Die anderen Medaillons, die wir bereits gefunden haben, werden uns zu ihm führen.\n\nWir treffen uns in Sündensturz. Und bringt Euren Schreckenslordjagdtrupp mit. Ich vermute, wir werden ihn brauchen.", sourceObjective = "Trefft Euch mit Prinz Renathal in Sündensturz.", completion = "Die Nathrezim sind vielleicht keine Venthyr, aber sie wurden auch nicht aus Seelen erschaffen. In vielerlei Hinsicht habe ich mehr mit ihnen gemein als mit anderen Venthyr.\n\nEs ist eine Schande, dass sie diesen Weg eingeschlagen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63651] = { id = 63651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kryptogramme", description = "Sollten die Nathrezim wirklich Sündensturz unterwandert haben, dann müssen sie kommunizieren. Und das nicht nur mit Handzeichen und Worten. Sie verlassen sich mit Vorliebe auf magische schriftliche Nachrichten, die durch einen simplen Trick vor den Blicken Unbedarfter verborgen bleiben.\n\nAber ich habe eine Beschwörungsformel entworfen, mit deren Hilfe Ihr diese Nachrichten sehen könnt.\n\nFindet die Kryptogramme und bringt mir ihren Inhalt. Ich kann sie für Euch übersetzen, falls Ihr sie nicht versteht.", sourceObjective = "Übertragt 10 infernale Kryptogramme.", completion = "Das ergibt keinen Sinn. Ihre Ziele sind viel zu weit verteilt. Ich hatte vermutet, sie wollten mein Medaillon stehlen, damit wir das neue Siegel der Venthyr nicht vollenden können, aber das war anscheinend noch längst nicht alles.\n\nWas haben sie wirklich vor? Hier, nehmt diese übersetzte Kopie.", sourceObjectiveStatus = "unverified-source-field" }
quests[63652] = { id = 63652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die \"ungebetenen\" Gäste", description = "Chelra, ich meine Nal'ragas, hat bestimmt nicht allein gearbeitet. Wir müssen das Schlimmste annehmen: dass nicht all unsere Freunde und Verbündeten das sind, was sie zu sein vorgeben.\n\nEs wird eine Weile dauern, bis der Hof der Ernter unser Aufdeckungsritual abgeschlossen hat. In der Zwischenzeit sind wir angreifbar. Daher bitte ich Euch: Setzt dieselben Taktiken ein wie am Tor der Dominanz in Sündensturz und befreit unsere Reihen von den Nathrezim.\n\nErfolgreiche Jagd.", sourceObjective = "Beseitigt 3 Nathrezim in Sündensturz.", completion = "List und Spionage haben noch nie zu meinen Stärken gehört. Ständig werden neue Seelen hierhergeschickt, die in solchen Dingen viel besser sind als ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[63653] = { id = 63653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht einer Krone", description = "Wir sind bereit.\n\nDer Hof der Ernter wird uns mit der Macht der Medaillons, die wir bereits gefunden haben, zum Medaillon des Zorns führen. Wenn es sich noch immer in diesem Reich befindet, dann sollten wir es eigentlich orten können.\n\nDieses Ritual ist nicht einfach. Die Nathrezim sind wahre Meister der Tarnung. Wenn sich Euch der Pfad offenbart, dann beeilt Euch.\n\nWenn Ihr sie dann findet, wartet auf uns, bevor Ihr angreift.", sourceObjective = "Findet den Pfad zum Medaillon des Zorns.", completion = "Ich lasse nicht zu, dass diese ungebetenen Gäste sich mit meinem Medaillon davonstehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63654] = { id = 63654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nathrezim", description = "Das Medaillon des Zorns ist nicht nur ein mächtiges Artefakt. In den Fängen der Nathrezim ist es eine Gefahr für das gesamte Reich. Und solange sie darüber verfügen, sind wir nicht in der Lage, ein neues Siegel zu erschaffen.\n\nMit ihren Machenschaften hätten sie schon fast den Glutdistrikt zerstört. Ich lasse nicht zu, dass sie mein Medaillon für ihre Zwecke missbrauchen.\n\nKommt, holen wir es uns zurück.", sourceObjective = "Holt das Medaillon des Zorns von den Nathrezim zurück.", completion = "Dies ist schlimmer als alles, was ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[63655] = { id = 63655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medaillon des Zorns", description = "<Schlundgänger/Schlundgängerin>, ich werde mit meinen Steingeborenen in die Tiefen des Schlunds marschieren und jedem Nathrezim, den ich dort finde, den Kopf abreißen.\n\nAllerdings ist Revendreth in diesem Krieg strategisch immer noch viel zu wichtig, um rein aus fehlgeleiteter Eitelkeit seinen Verlust zu riskieren.\n\nAus diesem Grund biete ich, die Ernterin des Zorns, Zweite dieses Titels, Euch an, mein Medaillon gut zu verwahren und zu verwenden, während ich in diesen Krieg ziehe.\n\nVerwendet es zur Stärkung der Ernter, damit sie Denathrius daran hindern können, einfach zurückzukehren und im Handumdrehen die Kontrolle wiederzuerlangen.", sourceObjective = "Bringt das Medaillon des Zorns zum Podium in Sündensturz.", progress = "<Die Plattform vibriert vor Energie, als sie die Nähe des Medaillons spürt.>", completion = "<Das Einsetzen des Medaillons in den Sockel zerrt heftig an Eurer Seele, während sich die Energien verbinden und ein Gefühl des Willens und der Absicht in alles um Euch herum einfließen lassen, wie Ihr es bei noch keiner anderen Energie erlebt habt.\n\nGemeinsam regieren die Ernter unangefochten über Revendreth.>", sourceObjectiveStatus = "unverified-source-field" }
quests[63656] = { id = 63656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedeutung des Zorns", description = "Ich werde meine Streitkräfte sammeln und sofort einen Teil davon nach Korthia entsenden. Und ich werde dafür sorgen, dass ihnen die Werkzeuge zur Verfügung gestellt werden, die Baronin Vashj und Kael'thas herbeizaubern konnten, um uns weiter gegen die Übergriffe der Nathrezim zu verteidigen.\n\nAndere Aufgaben erfordern meine Aufmerksamkeit, bevor ich nach Korthia reisen kann. Ich muss die Herrschaftsburg gegen weitere Eindringlinge sichern.\n\nIch vermute, dass der Primus eine Meldung erwartet. Ihr könnt ihm sagen, dass Ihr erfolgreich wart.", sourceObjective = "Erstattet dem Primus Bericht.", completion = "Eure Stärke im Kampf bleibt unerreicht. Heute aber habt Ihr diplomatische Stärke bewiesen.\n\nIch habe bereits Befehle für den Einsatz der Truppen der Steinhauerin erteilt. Gut, dass Ihr sie ins Spiel gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63659] = { id = 63659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckenslords!", description = "Das ist diese Woche schon der fünfte Schreckenslord, den wir in unseren Reihen gefunden haben. Wenn wir sie nicht alle finden, könnten sie in unserem Stützpunkt hier großen Schaden anrichten.\n\nZu meinen Lebzeiten habe ich von einem Dämonenjäger gelernt, wie man diese Kreaturen identifiziert. Aber auch, wenn ich sie so leichter aufspüren kann, kann ich nicht überall gleichzeitig sein.\n\nWir müssen dem Primus berichten, was wir herausgefunden haben.", sourceObjective = "Sprecht mit dem Primus in Korthia.", completion = "Noch mehr Schreckenslords? Ich hätte wissen müssen, dass wir nicht ewig von Denathrius' Fängen verschont bleiben.\n\nAber es freut mich, dass das Haus der Augen trotz seiner Rückschläge während meiner Abwesenheit noch nicht vollkommen erblindet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63660] = { id = 63660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg in den Schlund", description = "Der Kerkermeister hat ein weiteres Siegel errungen und seine Streitkräfte stürzen sich auf Oribos.\n\nBolvar Fordragon und Draka aus Maldraxxus wollen den Kerkermeister direkt angreifen.\n\nDazu brauchen wir erst einen Weg, über den ihre Streitkräfte den Schlund sicher betreten und wieder verlassen können.\n\nVor Eurer Ankunft hatten wir so etwas für unmöglich gehalten... doch nun glaube ich, dass es eine Möglichkeit geben könnte.\n\nIch muss Eure Anima untersuchen, um festzustellen, ob dies wahrlich der Wille der Vorsehung ist.", sourceObjective = "Erlaubt Tal-Inara, Eure Anima zu untersuchen.", completion = "Dieser Schritt fällt mir nicht leicht, Schlundgänger, aber es bleibt uns keine Wahl.\n\nWir müssen ein Tor zum Schlund öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63661] = { id = 63661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verbindung zum Schlund", description = "Der Schicksalsschreiber ist sich sicher, dass ein zweiter Portalstein im Schlund aufgetaucht ist. Es obliegt Euch, ihn zu finden.\n\nIch werde einen Anker hier in Oribos erschaffen, der mit Eurer Anima verbunden ist. Sobald Ihr Euch auf den Portalstein einstimmt, wird mein Anker an ihn gebunden.\n\nWenn Ihr erfolgreich seid, können die Truppen der Pakte den Schlund sicher betreten und wieder verlassen.\n\nNutzt, was auch immer Euch im Schlund an Ressourcen zur Verfügung steht, um diesen Portalstein zu finden.\n\nViel Glück, <Sterblicher/Sterbliche>. Möge die Vorsehung uns alle leiten.", sourceObjective = "Befragt Ve'nari zum Standort des zweiten Portalsteins.", progress = "Ich kenne diesen Ausdruck von Euch, Schlundgänger.\n\nIhr seht aus, als wolltet Ihr mich um etwas bitten.", completion = "Im Normalfall würde ich Eure Bitte als lästig und beleidigend erachten.\n\nAber die jüngsten Ereignisse haben mich zu der Überzeugung gebracht, dass Euer Vorschlag sich für uns beide als vorteilhaft erweisen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[63662] = { id = 63662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Schlunds", description = "Der Schlund verändert sich, <Sterblicher/Sterbliche>. Und mit Veränderungen tun sich neue Möglichkeiten auf.\n\nDer Kerkermeister hat ein Reich, das tief in den Schattenlanden verborgen lag, in den Schlund gezogen. Ich habe ein gewisses Interesse daran, möchte dort aber nicht allein hingehen.\n\nDas gesamte Gebiet wimmelt nur so von Schlundgebundenen. Es muss dort etwas Wertvolles geben, nach dem sie suchen.\n\nIch habe ein sicheres Versteck in der Nähe. Begleitet mich dorthin, dann kann ich Euch womöglich helfen, diesen Portalstein zu finden.\n\nHaben wir also eine Abmachung?", sourceObjective = "Reist mit Ve'nari zu der neuen Landmasse im Schlund.", completion = "Der Kerkermeister braucht unbedingt etwas von hier und doch kann sein kostbares Auge die Verteidigung nicht durchdringen.\n\nNun ja. Wollen wir?", sourceObjectiveStatus = "unverified-source-field" }
quests[63663] = { id = 63663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korthia, die Stadt der Geheimnisse", description = "Wir stehen kurz davor, unsere Wünsche zu verwirklichen, <Schlundgänger/Schlundgängerin>.\n\nEs ist bestimmt nicht mehr weit bis zu Eurem großen Portalstein. Meine Ansprüche sind natürlich weitaus bescheidener. Ein paar nützliche Informationen hier, ein unbezahlbares Relikt dort...\n\nIch werde das Gebiet erkunden, um zu sehen, ob es in der Nähe etwas Nützliches oder gar Gefährliches gibt. Dann können wir fortfahren.", sourceObjective = "Wartet, bis Ve'nari das Gebiet untersucht hat, und seht Euch dann genauer an, was immer sie findet.", completion = "Ich muss mehr über Euch herausfinden, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[63664] = { id = 63664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt zum Punkt", description = "Unsere Stellung bei der Brücke zum Altar der Herrschaft wird angegriffen! Wir dürfen unsere Balliste dort auf keinen Fall verlieren.\n\n<Schlundgänger/Schlundgängerin>, Ihr müsst diese Stellung verteidigen, bis unsere Truppen für ihren Vorstoß bereit sind!", sourceObjective = "Verteidigt den Brückenkopf in der Verdammnisfestung.", completion = "Der Sieg wird unser sein, Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[63665] = { id = 63665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg nach Oribos", description = "Die Prophezeiungen haben uns gesagt, dass dieser inaktive Portalstein eines Tages von einem Schlundgänger gebraucht werden würde. Und dass er sich als entscheidend für das Schicksal der Schattenlande erweisen würde.\n\nEs scheint, dass dieser Tag nun gekommen ist.\n\nMithilfe der Anima in Euch könnt Ihr diesen Portalstein aktivieren. Er wird dann von all jenen benutzt werden können, die Euch unterstützen.\n\nWenn Tal-Inara, wie Ihr behauptet, tatsächlich einen Anker in Oribos geschaffen hat, wird Euch dieser zu uns zurückbringen.\n\nUnd nun geht, {name}. Teilt Euren Verbündeten mit, dass der Schlund sie erwartet... und dass Korthia ihre Hilfe braucht.", sourceObjective = "Aktiviert den Portalstein und reist nach Oribos.", completion = "Gut gemacht, {name}. Ich bin gespannt auf dieses Reich, das in den Schlund gezogen wurde.\n\nEs wird Zeit, dass wir unseren Angriff auf die Truppen des Kerkermeisters beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63669] = { id = 63669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann mal jemand Kevin füttern", description = "Meine Schleimfamilie hungert stets nach Anima. Glücklicherweise sind die Körper der Gefallenen hier eine gute Quelle dafür!\n\nJe mehr die Schleime verschlingen, desto größer werden sie. Und was dann noch von den Gefallenen verbleibt, wird Teil unserer wundervollen, glücklichen Familie.\n\nNehmt Kevin und lasst ihn gefallene Feinde verschlingen, bis er voll ausgewachsen ist. Dann könnt Ihr ihn auf unsere Widersacher hetzen!", sourceObjective = "Lasst Kevin 8 gefallene Feinde verschlingen, um ihn zu voller Größe anwachsen zu lassen.", completion = "Der Sieg wird unser sein, Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[63671] = { id = 63671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunst: Die Dokumente der Nathrezim", description = "Dieser Gegenstand wird die Mittler sicher interessieren.\n\nIhr solltet ihn gemäß der Abmachung mit dem Nachtmarkt direkt zu Ta'xera bringen.\n\nMan wird Euch dafür gebührend entlohnen.", sourceObjective = "Bringt die Dokumente der Nathrezim zu Ta'xera auf dem Nachtmarkt in Revendreth.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[63672] = { id = 63672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf aus tiefstem Herzen", description = "<Die Stimme von Ysera erklingt aus der Schriftrolle, während Ihr die Worte lest.>\n\n{name},\n\nich benötige Eure Hilfe bei einer äußerst wichtigen Angelegenheit. Ich erwarte Euch im Herz des Waldes. Kommt bitte, so schnell Ihr könnt.", sourceObjective = "Trefft Euch mit Ysera im Herz des Waldes.", completion = "Danke, dass Ihr so schnell gekommen seid, {name}. Der Ardenwald braucht Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[63673] = { id = 63673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd zwischen den Häusern", description = "Ich habe gute Nachrichten, {name}. Da die Pakte jetzt enger zusammenarbeiten, ist auch Hulns Jagd von mehr Erfolg gekrönt. Er hat gute Hinweise auf zwei weitere Nachtkrieger hier in den Schattenlanden.\n\nFür den Ersten erwartet er Euch in Maldraxxus am Grabmal des Wissens.\n\nBeeilt Euch, {name}. Elunes Macht droht, Tyrande zu zerreißen. Ich weiß nicht, wie lange sie noch durchhält.", sourceObjective = "Findet Huln Hochberg in Maldraxxus.", completion = "Meine fortlaufende Suche nach weiteren Nachtkriegern hat mich hergeführt, {name}. Gemeinsam werden wir sie finden und um Hilfe bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63674] = { id = 63674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Ihr gestattet", description = "Meine Baronin, Lady Vashj, hat mir eine Aufgabe übertragen. Mit etwas Unterstützung wäre meine Rache geschwind. Doch sie muss Eurer Hilfe erst zustimmen und mir erlauben, Euch bei Eurer Aufgabe zu begleiten.\n\nGeht zum Sitz des Primus. Dort werden wir mit ihr sprechen.", sourceObjective = "Trefft Euch mit Lady Vashj beim Sitz des Primus und bittet um Khaliiqs Hilfe.", completion = "Mit Eurer Hilfe sollte meine Liste im Nu erledigt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63675] = { id = 63675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt kein Entkommen", description = "Zelmany war dafür verantwortlich, dass mein Markgraf gefallen ist.\n\nSin'dane glaubt, dass er Kel'Thuzads loyale Truppen um sich zu versammeln versucht, damit sie ihn bei seinen nächsten Plänen unterstützen.\n\nWir sollten nach Hinweisen auf seinen Aufenthaltsort suchen und ihn dann töten.", sourceObjective = "Sammelt Hinweise und tötet anschließend Zelmany.", progress = "Die Verräter können nicht entkommen!", completion = "Einer der Anführer ist tot, aber ich werde erst ruhen, wenn sie alle tot sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[63676] = { id = 63676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstecken ist zwecklos", description = "Es gibt noch einige, die ihre Unterstützung für Kel'Thuzad niemals öffentlich gezeigt haben. Auch nicht nach seinem Coup. Aber auch sie waren am Sturz meines Markgrafen beteiligt und auch sie werden dafür sterben.\n\nIch habe erst einen Namen, Drava'ora, aber da sind noch mehr. Sin'dane glaubt, diese Verräter tragen alle ein Zeichen der Gunst. Sie weiß nicht, wer solch ein Zeichen hat, also töten wir einfach so lange, bis wir sie finden.\n\nDieses Exempel wird dem Rest von ihnen nicht lange verborgen bleiben.", sourceObjective = "Findet Zeichen von Kel'Thuzads Gunst und tötet Drava'ora.", progress = "Der Rest von ihnen wird sich aus Angst fügen.", completion = "Verräter können sich nicht verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[63677] = { id = 63677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr könnt nur sterben", description = "Der letzte Name auf meiner Liste ist ein Lich namens Fal'zinge.\n\nSin'dane hat ihn genau im Auge behalten, um mehr über Kel'Thuzads Pläne zu erfahren.\n\nFal'zinges Ende soll so schmerzhaft wie möglich sein.\n\nWir sollten ihn auf der Exoramas im Haus der Rituale finden.", sourceObjective = "Tötet Fal'zinge auf der Exoramas.", completion = "Dies ist das einzige Ende für alle, die Maldraxxus verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63678] = { id = 63678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Akarek", description = "Die letzten Verräter an Markgraf Akarek sind tot.\n\nDas bringt unseren Markgrafen zwar nicht zurück, aber ich bin trotzdem zufrieden.\n\nMeine Baronin wünscht, dass wir Markgräfin Sin'dane von diesem Erfolg berichten, bevor wir zum Ardenwald aufbrechen.", sourceObjective = "Trefft Euch mit Markgräfin Sin'dane auf der Exoramas im Haus der Rituale.", completion = "Wir dulden keine Verräter.", sourceObjectiveStatus = "unverified-source-field" }
quests[63679] = { id = 63679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Mysterien!", description = "<Lady Mondbeere Stimme erklingt aus der Schriftrolle.>\n\n{name}! Anscheinend hat sich Huln einigen Ärger eingehandelt. Und... nun ja... es ist kompliziert. Wir könnten wirklich Eure Hilfe in Revendreth brauchen! Ich erwarte Euch in der Herrschaftsburg.\n\nBis bald!", sourceObjective = "Findet Lady Mondbeere in Revendreth.", completion = "Ich bin froh, dass Ihr so schnell gekommen seid. Wir haben hier ein kleines Problemchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63680] = { id = 63680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Abgrund", description = "Es klingt, als wäre Huln woanders hingebracht worden, und zwar von der Steinhauerin selbst!\n\nWir sollten nach Hinweisen suchen, die sie hinterlassen haben könnte, als sie durch diese Gegend kam. Das wird uns hoffentlich zu Huln führen!", sourceObjective = "Spürt Huln Hochberg auf.", completion = "Wir haben Huln gefunden, und dann war er auch noch genau bei der Person, der wir bei dem Ritual helfen müssen!\n\nIch liebe es, wenn alles so glatt läuft, Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[63681] = { id = 63681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Herz", description = "Wir sollten so schnell wie möglich zurück zum Ardenwald!\n\nGeht Ihr schon vor und sucht nach Ysera. Ich begleite die Steinhauerin dorthin und sorge dafür, dass Huln sicher zurückfindet.", sourceObjective = "Kehrt zu Ysera vor dem Herz des Waldes im Ardenwald zurück.", completion = "Bin ich froh, Euch wiederzusehen. Wir haben nicht viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[63682] = { id = 63682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht von Elune", description = "Wir haben in der uns zur Verfügung stehenden Zeit so viel getan, wie wir konnten.\n\nJetzt müssen wir Thiernax und den anderen unsere Kraft verleihen und hoffen, dass Tyrande überleben wird.", sourceObjective = "Helft bei der Durchführung des Rituals.", completion = "Es ist so lange her...", sourceObjectiveStatus = "unverified-source-field" }
quests[63683] = { id = 63683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des Winters", description = "Meine Schwester... Nach all dieser Zeit... Sie hat mich nicht aufgegeben...\n\n<Ein kaum wahrnehmbares Lächeln schmückt das Gesicht der Winterkönigin und verschwindet dann wieder. Sie sieht Euch mit der Last der Äonen in ihren Augen an.>\n\nBegleitet mich, {name}. Nehmt die Träne meiner Schwester und kommt mit zum Herz des Waldes.", sourceObjective = "Bringt die Träne der Schwestern zu Ysera im Herz des Waldes.", progress = "Gut gemacht.", completion = "<Ysera seufzt erleichtert.>\n\nFrieden ist in den Ardenwald und zu denen, die darin wohnen, zurückgekehrt. Meine liebe Freundin ist gerettet worden. Ich weiß nicht, was als Nächstes kommt, aber ich habe Hoffnung.\n\nOhne Eure Hilfe wäre dies nicht möglich gewesen, {name}. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[63684] = { id = 63684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilder Schemenhund", description = "<Die runenbeschriebene gepanzerte Hülle pulsiert vor Macht und scheint um ihre Freiheit zu kämpfen.\n\nGebt Euren wilden Schemenhund frei und bindet ihn an Euch.>", sourceObjective = "Beschwört und bindet Euren wilden Schemenhund.", sourceObjectiveStatus = "unverified-source-field" }
quests[63685] = { id = 63685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Grufthüter Kassir", sourceObjective = "{name}, bitte verzeiht, dass ich einmal mehr meine Dankbarkeit dafür zum Ausdruck bringen möchte, dass ich am Gluthof teilhaben durfte.\n\nDas ist die größte Ehre meines bisherigen Daseins, und es ehrt mich immens, dass ich dabei einen kleinen Teil zum Erfolg unseres Prinzen beitragen durfte.\n\nFalls ich Euch in Zukunft einmal mehr zu Diensten sein kann, so lasst es mich wissen, wertester Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[63686] = { id = 63686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Baronin Vashj", sourceObjective = "<Baronin Vashj lächelt Euch an.>\n\n{name}, Ihr habt Euch als willkommene Ablenkung von meinen derzeitigen Unterfangen erwiesen.\n\nDas soll nicht heißen, dass ich meine ursprüngliche Skepsis angesichts der Einladung zu Eurem Gluthof bereue, doch ich muss zugeben, dass Ihr jegliche Bedenken zerstreut habt.\n\nIhr und Prinz Renathal wisst, wie man einen vorzüglichen Gluthof veranstaltet, und es freut mich, mehr Zeit mit Euch verbracht zu haben.\n\nBis zum nächsten Gluthof, mein kleiner {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63687] = { id = 63687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Lady Mondbeere", sourceObjective = "<Lady Mondbeere verkneift sich ein Lachen.>\n\n{name}! Ich habe Goji gerade von unserem allerersten gemeinsamen Gluthof erzählt. Ihr erinnert Euch noch? Ich habe für die Illusionen gesorgt und versucht, Prinz Renathal mit meinem ganz eigenen... nun, das brauche ich Euch ja nicht noch einmal zu erzählen. Ihr wart ja schließlich dort!\n\nWir zwei sind echte Seelenverwandte...", sourceObjectiveStatus = "unverified-source-field" }
quests[63688] = { id = 63688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Mikanikos", sourceObjective = "Ich mag Euch, {name}.\n\nStarker {name}.\nKluger {name}.\nAbenteuerlustiger {name}.\n\nWie Bron, aber kleiner... und besser?\n\n\n\nJa, besser!\n\n{name} ist bester Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[63689] = { id = 63689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund der Gräfin", sourceObjective = "Jeder Eurer Schritte hier verleiht dem Redelavturm einen freudigen Glanz, {name}.\n\nIch wünschte, Ihr könntet uns öfter besuchen, aber so ist das nun mal mit besten Freunden, meint Ihr nicht auch?\n\n\n\nIch habe heute keine Bitte an Euch, mein Lieber. Es geht mir allein um Eure Freundschaft.\n\nEuch ist ja gewiss bewusst, wie selten man unter all den Bücklingen am Hof wahre, aufrichtige Freundschaften findet.\n\nJa, natürlich wisst Ihr das, Ihr seid schließlich der Gastgeber des vorzüglichsten Hofs in ganz Revendreth!", sourceObjectiveStatus = "unverified-source-field" }
quests[63690] = { id = 63690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Alexandros Mograine", sourceObjective = "Es war mir eine Ehre, an Eurer Seite zu kämpfen, {name}. Und vielleicht sogar eine noch größere Ehre, gemeinsam mit Euch zur Wiedervereinigung Revendreths beizutragen.\n\nIhr werdet bis ans Ende unserer Zeit hier mein Waffenbruder sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63691] = { id = 63691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Jagdhauptmann Korayn", sourceObjective = "<Jagdhauptmann Korayn steckt lächelnd ihre Waffe weg.>\n\nAh, endlich kann ich mich etwas entspannen. {name} ist da!\n\nSolange der mächtige Schlundgänger unter uns weilt, wird kein Unheil über uns kommen. Selbst die Gorm bekommen nun das große Zittern, wenn sie Euren Namen hören.\n\n{name}, unser Band ist durch die vielen Schlachten, die wir gewonnen, und die Höfe, die wir erobert haben, ungemein stark geworden.\n\nWohin uns die Jagd als Nächstes auch führen mag, ich hoffe, wir reisen gemeinsam dorthin.", sourceObjectiveStatus = "unverified-source-field" }
quests[63692] = { id = 63692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Polemarch Adrestes", sourceObjective = "<Polemarch Adrestes unterdrückt ein Lachen, da das Gefühl ihm ungewohnt erscheint.>\n\n{name}, ich hatte gerade einen Tagtraum über das erste Mal, als Ihr mich zum Gluthof eingeladen habt. Erinnert Ihr Euch noch?\n\nIch wollte die Verantwortung eigentlich auf jemanden abschieben, der dieser Herausforderung besser gewachsen zu sein schien, doch Chyrus war der Ansicht, das sei eine gute Gelegenheit für mich, als Person zu reifen.\n\nUnd wie recht er damit hatte! Was haben wir gemeinsam nicht alles geleistet... und wir hatten sogar ein bisschen Spaß dabei!\n\n\n\nIhr habt mich in vielerlei Hinsicht besser gemacht, werter Freund. Habt vielen Dank dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[63693] = { id = 63693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Rendel und Knüppelfratze", sourceObjective = "Ich und Rendel, wir haben grad über Euch gequatscht, {name}.\n\nEr hat allen Gräbern erzählt, Ihr wärt SEIN bester Freund, aber ich weiß genau, dass Ihr MEIN bester Freund seid. Und Rendel ist auch schon immer mein bester Freund gewesen. Mann, das bringt mich jetzt aber total durcheinander.\n\nKönnen wir nicht einfach alle zusammen beste Freunde sein? Das wär doch was, oder?\n\nUnd unsere Freundschaft ist aus dem festesten Schlamm gebaut. Beste Freunde für immer, sag ich. BFFI, nenn ich das.\n\nUnd BFFI helfen den anderen immer aus'm Schlamassel. Sagt dem alten Rendel und mir einfach Bescheid, wann und wo Ihr uns mal brauchen tut!", sourceObjectiveStatus = "unverified-source-field" }
quests[63694] = { id = 63694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Choofa", sourceObjective = "Es ist offiziell, {name}. Rury, Slanknen, Awool, ich... also die ganze Bande... wir haben über unseren besten Freund geredet, also EUCH! Und wir finden, dass Ihr bereit seid, Euch uns anzuschließen.\n\nAlso, willkommen in der Bande, bester Freund! Amüsieren wir uns ein bisschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[63695] = { id = 63695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Dromanin Aliothe", sourceObjective = "Ich habe im Leben ja schon viel gesehen, {name}. Aber nach so vielen Gluthöfen kann ich mit einiger Gewissheit sagen, dass ich etwas oder jemanden wie Euch noch nie zuvor erlebt habe.\n\nIhr und Euer Prinz habt mich dazu gebracht, sowohl über den Sinn meines Daseins als auch mein Schicksal nachzudenken. Ich weiß zwar nicht, wie dieses Abenteuer, zu dem wir gemeinsam aufbrechen, am Ende ausgehen wird, doch sollte ich fallen, so hoffe ich, dass es an Eurer Seite geschieht.\n\nRuft mich, wann immer Ihr mich braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63696] = { id = 63696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Großmeister Vole", sourceObjective = "Ich habe ein echtes Auge für Talent. Das habe ich mir gedacht, als ich Euch das erste Mal in der Arena gesehen habe: \"Der Junge wird es noch weit bringen.\"\n\nUnd hier stehe ich nun und begleite Euch auf Eurer Reise.\n\n<Großmeister Vole lächelt aufrichtig, als er sich einen Augenblick lang entspannt.>\n\nIch bin Euch was schuldig, Junge.\n\nUnd wisst Ihr, hier begegnet man nicht vielen, die das Zeug zum Freund haben, auch wenn Ihr mir das vielleicht nicht glaubt.\n\nAlle zukünftigen Buchungen gehen übrigens aufs Haus. Für meinen besten Freund habe ich nämlich immer Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[63697] = { id = 63697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Kleia und Pelagos", sourceObjective = "War unsere gemeinsame Reise nicht fantastisch, {name}? Wir mögen zwar keine Seelenbande sein, doch mein Gefühl sagt mir, dass wir auf andere Weise miteinander verbunden sind.\n\nVerbunden durch eine Bestimmung, ein Ziel und eine starke Freundschaft.\n\n\n\nWelche Gefahren uns auch immer erwarten mögen, wenn wir dem Kerkermeister gegenübertreten... wir werden uns ihnen gemeinsam stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63698] = { id = 63698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Seuchenerfinder Marileth", sourceObjective = "Mein wunderbarer, glorreicher, außergewöhnlicher, intelligenter, geistreicher, kreativer, unverwüstlicher, zäher Lehrling {name}!\n\nEs freut mich ungemein, Euch sagen zu können, dass Ihr Euch eine Beförderung verdient habt! Ich weiß ehrlich gesagt gar nicht, welcher Titel über dem des Lehrlings steht... Keiner meiner Lehrlinge hat es jemals so weit gebracht.\n\nEure erste Aufgabe als mein neuer bester Lehrlingsfreund ist es, einen angemessenen Titel für Eure neue Position zu finden!\n\nHerzlichen Glückwunsch! Ihr untersteht nun direkt Kevin.", sourceObjectiveStatus = "unverified-source-field" }
quests[63699] = { id = 63699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Sika", sourceObjective = "Danke, {name}. Habt Sika gezeigt, dass sie viele Freunde hat.\n\n{name} ist bester Freund. Zeigt Sika Ruhe und Spaß. Zeigt Sika Güte.\n\nSika hilft Euch, {name}. Immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[63700] = { id = 63700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bester Freund von Steinkopf", sourceObjective = "Bester Kumpel!\n\nIhr habt mir doch ganz oft so Schreiben mitgebracht. Die kann ich jetzt lesen, hat mir Sibylle beigebracht!\n\nWisst Ihr, dass in den Schreiben steht, dass ich ganz oft feiern gehen kann? Lesen ist lustig! Lesen heißt feiern!\n\nSteinkopf feiert jetzt immer mit bestem Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[63703] = { id = 63703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archiv der Geheimnisse", description = "Ihr habt uns geholfen, zumindest den Anschein von Ordnung wiederherzustellen, <Schlundgänger/Schlundgängerin>. Aber die Aussichten gestalten sich finster.\n\nDie Truppen des Kerkermeisters haben einen Großangriff auf die Ruinen unseres Archivs in den abgelegeneren Bereichen von Korthia gestartet. Offensichtlich sucht der Verbannte darin etwas Wertvolles.\n\nDie Verteidigung des Archivs wird aktiviert, wenn es bedroht wird. Es wird also nicht einfach sein, hineinzukommen. Aber wir müssen bergen, was der Kerkermeister sucht, bevor seine Schlundgebundenen es tun.\n\nIch konnte einen Nekrolord überzeugen, uns bei der Öffnung des Archivs zu helfen.", sourceObjective = "Trefft Euch mit Tal-Galan an der Höhle des Gelehrten.", completion = "Wir haben unsere Schmiedin. Jetzt müssen wir den Plan umsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63704] = { id = 63704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Korthia", description = "Das Öffnen des Archivs hat zwar Priorität, aber ich muss Euch um einen Gefallen bitten.\n\nAls Korthia in den Schlund gezogen wurde, wurde mein Volk von Entsetzen ergriffen. Wir sind in das Gebiet geflüchtet, das Ihr vor Euch seht. Ein friedlicher Ort, den man die Höhle des Gelehrten nennt.\n\nDoch schon bald sind die Schlundgebundenen über uns hergefallen. Die meisten wurden niedergemetzelt. Andere wurden gefangen genommen.\n\nIch würde selbst Rache nehmen, wenn ich könnte. Aber ich... ich bin nicht für den Kampf gerüstet, anders als Ihr.\n\nBitte zeigt diesen Ungeheuern, dass wir die Entweihung Korthias nicht hinnehmen!", sourceObjective = "Tötet 15 Schlundgebundene in der Höhle des Gelehrten.", completion = "Rache wird die Gefallenen nicht zurückbringen, aber sie verschafft denjenigen von uns, die überlebt haben, ein gewisses Maß an Genugtuung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63705] = { id = 63705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hüter des Wissens", description = "Unser Archiv wurde gebaut, um unzählige Geheimnisse und Artefakte zu verwahren. Selbst wenn wir Zutritt erhalten, können wir nicht sicher sein, wonach der Kerkermeister sucht.\n\nBestimmte Bedienstete fungieren als Aufzeichnungshüter. Sie verfolgen die im Archiv gelagerten Gegenstände und sind für äußerste Diskretion bekannt.\n\nEin paar der Hüter wurden von den Schlundgebundenen gefangen genommen. Man foltert sie, um Informationen aus ihnen herauszupressen.\n\nBitte rettet die Aufzeichnungshüter, {name}. Mit ihrer Hilfe können wir herausfinden, wonach der Verbannte sucht!", sourceObjective = "Rettet 5 Aufzeichnungshüter aus der Höhle des Gelehrten.", completion = "Ich empfinde Erleichterung darüber, mehr meines Volks aus den Klauen des Kerkermeisters befreit zu sehen.\n\nNun gilt es herauszufinden, wonach er sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63706] = { id = 63706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Anima fließen", description = "Tal-Galan hat mir die Situation und die Funktionsweise des Archivs erklärt. So gut, wie es diesen Gelehrten nun mal möglich ist.\n\nZuerst müssen wir die Energieversorgung des Archivs sicherstellen. Sie verwenden unterirdische Leitungen, um es mit Anima zu versorgen.\n\nDer Bedienstete sagt, dass eine dieser Leitungen in der Höhle des Gelehrten untergebracht ist.\n\nWenn Ihr mich dort hinbringt, kann ich sie vielleicht reparieren. Passt einfach auf mich auf, während ich herausfinde, wie diese korthianischen Geräte funktionieren.", sourceObjective = "Helft Knochenschmiedin Heirmir, die Animaleitung zu reparieren.", completion = "Nach der Dürre, die die Schattenlande erlitten haben, werde ich fließende Anima nie wieder als gegeben ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63708] = { id = 63708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantasmagorie", description = "<Das seltsame fremde Energiepartikel pulsiert in einem ungleichmäßigen Rhythmus.\n\nVe'nari könnte das sehr interessieren.>", sourceObjective = "Bringt das verformte Phantasma zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Wie wunderschön. Dass dieses Phantasma überhaupt außerhalb des Turms existieren kann, ist ein Wunder. Seine ganze Art ist äußerst kurios... Ich sollte es eingehend studieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63709] = { id = 63709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Archivs", description = "Was für ein Segen! Ihr habt die Aufzeichnungshüter gerettet, bevor die Schlundgebundenen ihnen das Wissen über die Relikte im Archiv stehlen konnten.\n\nAber die Aufzeichnungen sind fragmentiert. Unvollständig. Ich hoffe, dass genug übrig ist, um die Wahrheit zu erfahren.\n\nIch werde versuchen, das verbliebene Wissen in einer Mitteilung zusammenzufassen. Wenn die Vorsehung es so will, werden wir erfahren, was der Kerkermeister vorhat und wem dieser Gegenstand ursprünglich gehörte.\n\nIch muss mich für einen Moment konzentrieren. Lasst mich wissen, wenn Ihr bereit seid, anzufangen.", sourceObjective = "Untersucht die wiedergewonnenen Aufzeichnungen mit Tal-Galan.", completion = "Wir wissen, was der Kerkermeister sucht.\n\nNun müssen wir das Archiv erreichen, bevor seine Streitkräfte es einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63710] = { id = 63710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Animaspur", description = "Der Kerkermeister sucht also das Siegel des Primus. Wir müssen vor den Schlundgebundenen dort sein. Um das Archiv zu öffnen, benötigen wir Anima.\n\nIhr habt der Knochenschmiedin dabei geholfen, die erste Leitung zu reparieren. Diese Animaspur führt uns zur nächsten Leitung.\n\nWenn wir sie aktivieren können, sollte genug Anima nach Korthia fließen, um den Weg in das Archiv zu öffnen.\n\nKommt, wir müssen uns beeilen!", sourceObjective = "Folgt der Animaspur bis zur nächsten Leitung.", completion = "Ein Abgrund!\n\nWir brauchen einen Weg, um zur nächsten Animaleitung zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63711] = { id = 63711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenwerkzeug", description = "Dann befindet sich das Gerät, mit dem wir dieses Archiv öffnen können, also auf einer schwebenden Insel?\n\nKein Problem.\n\nHier gibt es eine Menge äußerst zähe Wesen. Und wie ich immer sage: Bloß keine Knochen verkommen lassen!\n\nGeht und bringt mir einen Haufen Knochen. Ich fertige uns damit ein paar Ankerpunkte, mit denen wir per Wurfhaken auf die andere Seite kommen.", sourceObjective = "Sammelt 50 animaerfüllte Knochen von Wildtieren.", progress = "Vergesst nicht, ich brauche lediglich die Knochen. Fleisch ist nur im Weg.", completion = "Ja, damit kann ich etwas anfangen. Ich glaube, ich werde einen davon mit nach Hause nehmen und ihn den anderen Schmieden zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63712] = { id = 63712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Aufzeichnungen", description = "Einige Aufzeichnungshüter sind zu diesem Berg geflohen, als Korthia in den Schlund gezogen wurde.\n\nIch finde keine Spur von ihnen, doch vielleicht haben sie Aufzeichnungen zurückgelassen.\n\nNehmt dieses Signal. Ich habe es mithilfe der Informationen der zuvor von Euch geretteten Aufzeichnungshüter angefertigt.\n\nEs wird Euch zu etwaigen noch intakten Aufzeichnungen an diesem Berg führen.", sourceObjective = "Verwendet das Matrixsignal, um 3 verlorene Aufzeichnungen zu bergen.", progress = "Habt Ihr die Aufzeichnungen beschafft?", completion = "Ausgezeichnet. Aus diesen Aufzeichnungen sollte ich die Nachricht des Primus extrahieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[63713] = { id = 63713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz schön hakelig", description = "Ich habe ein paar solide Wurfhaken und Ankerpunkte gebaut. Keine Sorge, wenn sie mein Gewicht halten, werden sie auch Eures halten!\n\nDamit kommen wir über den Abgrund zur nächsten Animaleitung.\n\nIch gehe voraus und warte auf Euch. Wer weiß, was da drüben auf uns lauert.\n\nJe schneller die Animaleitung wieder funktioniert, desto schneller kommen wir in das Archiv, um uns das Siegel des Primus zu holen.", sourceObjective = "Reist per Wurfhaken zu der schwebenden Insel und repariert dann die Animaleitung.", completion = "Was für ein Ritt! Den Wurfhaken könnt Ihr behalten.\n\nAber vorsichtig damit. Normale Greifhakenziele halten diesem Ding nicht stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[63714] = { id = 63714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Archiv", description = "Nachdem die Knochenschmiedin nun beide Leitungen repariert hat, sollte die Anima zum Archiv fließen. Dadurch haben wir die Chance, dort reinzukommen... wenn wir es denn erreichen.\n\nUnsere Verbündeten aus Maldraxxus haben den Transport zum und vom Archiv vorbereitet. Wir sollten uns beeilen.\n\nWenn die Diener des Kerkermeisters das Siegel des Primus vor uns in die Finger bekommen, wird nicht nur Korthia darunter leiden. Die gesamten Schattenlande könnten für immer verloren sein.\n\nGehen wir, <Schlundgänger/Schlundgängerin>. Unsere Truppen warten auf uns.", sourceObjective = "Nehmt einen Fledderflügeltransporter zum Archiv der Geheimnisse.", completion = "Tal-Galan hat mir schon alles erklärt.\n\nWir müssen Euch in dieses Archiv bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63717] = { id = 63717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung des Archivs", description = "Um das Archiv zu erreichen, müssen wir uns einen Weg durch die angreifenden Schlundgebundenen bahnen.\n\nDie Pakte tun ihr Bestes, um diese Monstrositäten zu vertreiben, aber unsere Verbündeten werden nicht ewig durchhalten. Die Schlundgebundenen sind entschlossen, die Beute vor Euch zu erreichen.\n\nWir könnten Eure Hilfe im Kampf gegen die Truppen des Kerkermeisters brauchen, <Schlundgänger/Schlundgängerin>.\n\nMöge die Vorsehung uns alle leiten.", sourceObjective = "Helft Beschützerin Kah-Rev, die Invasion der Schlundgebundenen zurückzuschlagen.", completion = "Ihr habt wirklich tapfer gegen die Schlundgebundenen gekämpft.\n\nDen Rest übernehmen wir, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63718] = { id = 63718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theotars Ei", progress = "Genau wie die wahre Liebe, so ist auch mein Ei stets in Sichtweite, aber oft unerreichbar...", completion = "Ihr habt es gefunden! Ich bin sehr beeindruckt, werter Freund.\n\nSchulde ich Euch nun einen Kuss, oder bringe ich da wieder die Feiertage auf Azeroth durcheinander?" }
quests[63719] = { id = 63719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temels Ei", progress = "Ich habe mein Ei dort versteckt, wo ich unseren gesamten wichtigen Partybedarf aufbewahre...", completion = "Och, ich habe es Euch zu leicht gemacht, stimmt's?" }
quests[63720] = { id = 63720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinz Renathals Ei", progress = "Mein Ei ist der Mittelpunkt der Aufmerksamkeit, was ich mir auch für mich selbst erhoffe...", completion = "Ich muss gestehen, dass ich nicht im Traum daran gedacht hätte, einmal mit einem Ei Verstecken zu spielen... Ihr stammt wirklich aus einer ungemein kreativen Welt!" }
quests[63721] = { id = 63721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Garridans Ei", progress = "Wie ich immer zu sagen pflege: Haltet Eure Freunde nahe bei Euch, aber Eure Eier noch näher...", completion = "<Lord Garridan flüstert in Euer Ohr.>\n\nIch habe dafür gesorgt, dass meins leicht zu finden ist, damit die Gäste sich klug vorkommen. Es gibt viele Wege, jemandem zu schmeicheln." }
quests[63722] = { id = 63722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hüter von Korthia", description = "Wir konnten den Truppen des Kerkermeisters nur knapp standhalten. Aber mit Euch wird sich das Blatt bald wenden.\n\nIch weiß, dass Ihr unbedingt in das Archiv wollt, aber es gilt auch, unsere Aufzeichnungshüter zu retten.\n\nSie sind die Experten für alles, was sich im Archiv befindet. Wir dürfen nicht zulassen, dass der Kerkermeister herausfindet, was sie wissen.", sourceObjective = "Rettet 3 Aufzeichnungshüter im Archiv der Geheimnisse.", progress = "Gut, dass Ihr an unserer Seite kämpft, Schlundgänger.", completion = "Zu schade, dass nicht alle drei Hüter überlebt haben. Aber gut, dass Ihr zumindest zwei von ihnen gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63725] = { id = 63725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in das Archiv", description = "Die Zerstörung hier ist... erschütternd.\n\n<Tal-Galan spricht leise ein Gebet.>\n\nDie Anima fließt jetzt in die Überreste des Archivs. Wir müssten jetzt hineingehen können.\n\nSobald wir drinnen sind, werde ich versuchen, das Siegel des Primus zu sichern.\n\nBitte erweist dem Archiv Eure Ehrerbietung. Es ist ein heiliger Ort, den zu sehen nur wenigen gestattet ist.\n\nSelbst die Prophezeiungen haben nicht vorausgesagt, dass ein <ein lebender Sterblicher/eine lebende Sterbliche> die Geheimnisse im Inneren erblicken würde.", sourceObjective = "Findet das Siegel des Primus im Archiv von Korthia.", completion = "Das Siegel des Primus! Hm... Ich spüre eine vertraute Magie in ihm.\n\nJa, all die Dinge, die ich durch Eure Augen in Torghast gesehen habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[63726] = { id = 63726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwirrung des Siegels", description = "Das Siegel des Primus ist durch die Magie der Erinnerung gebunden. Es erinnert mich an etwas, das Euch schon einmal begegnet ist.\n\nIhr habt den Runenmetz, diese arme Seele, gefangen in den Eingeweiden von Torghast, zu einem Verbündeten gemacht. Er nahm die Erinnerungen, die Ihr gefunden hattet, und half Euch, sie zu Waffen und Rüstungen zu schmieden.\n\nVielleicht kann er das Siegel aus diesem Gewirr von Erinnerungen herauslösen.\n\nDas ist unsere beste Chance, das Siegel zu sichern. Aber der Weg ist gefährlich.", sourceObjective = "Beratet Euch mit Bolvar, was mit dem Siegel zu tun ist.", completion = "Wir sind frei. Das heißt also, dass der Kampf gegen Zovaal noch nicht verloren ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63727] = { id = 63727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Primus", description = "Der Kerkermeister besitzt nun vier der fünf Siegel für seinen Plan.\n\nAber es war töricht von ihm, uns am Leben zu lassen. Sein Verlangen, uns zu brechen, wird ihm zum Verhängnis werden.\n\nNoch ist nicht alles verloren. Vertraut auf Eure Stärke. Es gibt noch etwas, das wir tun können.\n\nKommt. Treffen wir uns mit dem Rest Eurer Streitkräfte und bereiten den nächsten Angriff vor.", sourceObjective = "Trefft Euch mit dem Primus in der Zuflucht des Hüters, um einen neuen Angriffsplan zu schmieden.", completion = "Über unsere Fehler der Vergangenheit können wir noch grübeln, wenn das hier vorbei ist. Jetzt müssen wir nach vorn sehen.\n\nIhr habt mir während meiner Gefangenschaft als Runenmetz geholfen. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[63728] = { id = 63728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd zwischen den Häusern", description = "Ich habe geträumt, dass Tyrande Wisperwind für das Überleben des Ardenwalds entscheidend ist.\n\nDie Nachtfae suchen schon lange nach anderen wie ihr, nach anderen ehemaligen Nachtkriegern. Wir haben einen uralten Verbündeten von Azeroth beauftragt, nach ihnen zu suchen: Huln Hochberg.\n\nElunes Macht ist zu überwältigend für ein sterbliches Wesen, selbst für Tyrande. Ich weiß nicht, wie lange sie das noch aushält.\n\nLasst mich das noch etwas weiter ausführen. Dann müsst Ihr Euch so schnell wie möglich mit Huln in Maldraxxus treffen.", sourceObjective = "Sprecht mit Ysera, um mehr zu erfahren, und sucht dann nach Huln Hochberg im Grabmal des Wissens.", progress = "Der Ardenwald weiß Eure Hilfe zu schätzen.", completion = "Eure Taten haben sich in den ganzen Schattenlanden herumgesprochen.\n\nIch weiß, zusammen werden wir diesen Nachtkrieger schnell finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[63731] = { id = 63731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korthianische Relikte erforschen", description = "<Ihr findet ein zerfleddertes Buch über die Relikte, die in Korthia verwahrt wurden.\n\nEin Name auf den Seiten des Buchs beginnt zu leuchten: \"Roh-Suir\".\n\nDas Buch dreht sich in Eurer Hand und weist in eine Richtung, während Roh-Suirs Name pulsiert.\n\nVielleicht könnt Ihr mithilfe von Roh-Suir mehr über die Relikte erfahren, die Ihr gefunden habt.>", sourceObjective = "Findet den Gelehrten Roh-Suir, um mehr über die Relikte zu erfahren.\n\nBereitgestellter Gegenstand:", completion = "Relikte? Forschung? Wir haben weitaus dringendere Probleme zu bewältigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[63732] = { id = 63732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhören stören", description = "Pssst... Leise!\n\nDie Eindringlinge werden mich töten, wenn sie mich hier finden. Wie schon so viele andere!\n\n<Roh-Suir gestikuliert wild in die Richtung der Schlundgebundenen.>\n\nSie foltern die Archivarin!\n\nIhr müsst einen Weg finden, sie zu retten. Wir können nicht zulassen, dass ihr großes Wissen in die Hände der Schlundgebundenen fällt!", sourceObjective = "Rettet Archivarin Roh-Senara.", progress = "Ohne Archivarin Roh-Senara gibt es keine Hoffnung. Ihre Sicherheit hat oberste Priorität.", completion = "Womit haben wir solche Grausamkeit nur verdient?", sourceObjectiveStatus = "unverified-source-field" }
quests[63733] = { id = 63733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Biegen und Breschen", description = "Obwohl ich Gewalt verabscheue und Konflikte bevorzugt mit Vernunft löse, gibt es in diesem Fall keine Alternative.\n\nDamit Roh-Suir und ich sicher entkommen können, müsst Ihr mit aller Macht die Schlundgebundenen angreifen, die in das Quorum des Suchers eingedrungen sind.\n\nSchlagt eine Bresche in ihre Reihen und bahnt uns einen Fluchtweg.", sourceObjective = "Besiegt 15 Eindringlinge der Schlundgebundenen.", completion = "Ihr habt uns genug Zeit für unsere Flucht verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[63734] = { id = 63734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gesplitterte Stab", description = "Mir bleibt keine Wahl. Ich muss Euch die Geheimnisse des Leitstabes anvertrauen.\n\nIn den richtigen Händen, wie zum Beispiel den Händen einer ausgebildeten Archivarin, kann der Stab mächtige Relikte aus den jenseitigen Leben der Schattenlande aufspüren.\n\nEr wurde in drei Teile zerschlagen, damit er niemals in falsche Hände gerät. Die Eindringlinge haben bereits die Teile gefunden haben, aber sie wissen noch nicht um ihre wahre Bedeutung.\n\nHolt die Teile des Stabes zurück. Jedes einzelne Segment befindet sich im Besitz eines unterschiedlichen Schlundgebundenen.", sourceObjective = "Beschafft die drei Segmente des Leitstabs wieder.", progress = "Ist es Euch gelungen, alle drei Segmente des Leitstabs wiederzubeschaffen?", completion = "Ich kann Euch gar nicht sagen, wie erleichtert ich bin, dass der Leitstab endlich unser ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63735] = { id = 63735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Forschung", description = "Die Umstände mögen trostlos sein, doch wir können die Vorsehung nicht vernachlässigen.\n\nBei den Leichen der Bediensteten im Quorum des Suchers werdet Ihr Schriftrollen finden, die unsere laufende Forschung dokumentieren. Was darin niedergeschrieben ist, entspricht der Arbeit vieler Eurer Lebzeiten.\n\nBringt uns diese Schriftrollen, bevor sie zerstört werden und für immer verloren gehen.", sourceObjective = "Rettet 6 Schriftrollen mit Gelehrtenforschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63736] = { id = 63736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Animainfusion", description = "Normalerweise würden wir den Leitstab mit der Energie aus dem Netherstern speisen, einem weiteren mächtigen Relikt.\n\nLeider ist das gerade unmöglich. Aber zur Not ist Anima ein recht brauchbarer Ersatz.\n\nNehmt den Leitstab. Haltet ihn über kürzlich gefallene Verschlinger dort unten im Ästuarium.\n\nDer Stab sollte ihnen dann die Anima entziehen und sie absorbieren.", sourceObjective = "Erfüllt den Leitstab mit Anima.", completion = "Der Leitstab vibriert förmlich vor neuer Energie! Die Anima hat besser funktioniert, als ich gehofft hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[63737] = { id = 63737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahre Vorsehung finden", description = "All Eure Bemühungen haben uns an diesen Punkt geführt.\n\nMit der geballten Weisheit der Archivare und ein wenig Hilfe von Euch als {class} werden wir den Leitstab auf die Relikte einstimmen, die wir benötigen.\n\nWenn uns das gelingt, wird das Archiv wiederauferstehen.\n\nUnd unsere heilige Pflicht kann fortgeführt werden.", sourceObjective = "Nehmt am Ritual der Einstimmung für den Leitstab teil.", completion = "So viel hat man uns genommen. Und doch gibt es noch Hoffnung, dank Roh-Senaras Opfer.", sourceObjectiveStatus = "unverified-source-field" }
quests[63738] = { id = 63738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbau des Archivs", description = "Ich begebe mich zur Zuflucht des Hüters, wo es zumindest einen kleinen Anschein von Sicherheit gibt.\n\nDort werden wir ein neues Archiv aufbauen.\n\nTrefft mich dort, wenn Ihr bereit seid.\n\nIch hoffe, ich kann weiterhin auf Eure Hilfe zählen. Denn auch dort werden wir Euch bald benötigen.", sourceObjective = "Trefft Euch mit dem Gelehrten Roh-Suir in der Zuflucht des Hüters.", completion = "Ich kann mir kaum vorstellen, wie ich ohne die Archivarin weitermachen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[63739] = { id = 63739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsteigende Hoffnung", description = "Es gibt noch eins, das wir erledigen müssen.\n\nTrefft uns oben auf dem Aufstieg der Hoffnung.", sourceObjective = "Trefft Euch mit Archivarin Roh-Senara und dem Gelehrten Roh-Suir oben auf dem Aufstieg der Hoffnung.", completion = "Ich dachte schon, Ihr hättet unsere Sache aufgegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63740] = { id = 63740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expertenrat einholen", description = "Wir können den Leitstab wiederherstellen, aber nicht ohne die Weisheit der Archivare.\n\nIch spreche nicht nur von mir, sondern auch von den vergangenen Archivaren. Sie wurden hier in der Nähe zur letzten Ruhe gebettet. Angesichts der gewaltigen Zerstörung in Korthia und auch der Tatsache, dass dies wohl noch längst nicht alles war, könnte dies unsere letzte Chance sein, ihre Gedenkstätten zu besuchen, bevor sie unrettbar ruiniert werden.\n\nSucht die Gedenkstätten der Archivare auf. Nehmt Roh-Suir mit, damit er ihre Nachrichten aufzeichnen kann, bevor sie auf ewig verloren sind.", sourceObjective = "Haltet Zwiesprache an den Gedenkstätten der Archivare.", completion = "Ich hoffe, Ihr und der Gelehrte Roh-Suir habt viel von den Archivaren gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63751] = { id = 63751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schreckliche Macht", description = "Der fremdartige Splitter pulsiert in Eurer Hand. Eine Aura des Schreckens strahlt von ihm aus wie ein frostiger Windhauch, der Euch einen Schauer über den Rücken jagt. Vielleicht kann Euch der Primus mehr darüber sagen... falls es Euch gelingt, ihn zu finden." }
quests[63753] = { id = 63753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zenturionen, marsch!", description = "Drei unserer Zenturionen haben das Seitentor durchbrochen. Sie brauchen zusätzliche Anima, um ihren Angriff fortzusetzen.\n\nMehrere meiner Assistenten haben versucht,sie ihnen zu bringen, leider erfolglos. Bitte bergt die Anima und unterstützt die Zenturionen bei ihrem Angriff.", sourceObjective = "Sammelt 5 Animapartikel, um die Zenturionen zu ermächtigen und im Kampf zu unterstützen.", progress = "Hatten die Zenturionen Erfolg?", completion = "Außergewöhnliche Arbeit, Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[63754] = { id = 63754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vogel im Käfig", description = "Seid still, niemand darf uns bemerken.\n\nViele meiner Schwestern sind schon verloren. Schon bald wird die Reihe an mir sein, für das grausige Ritual dieser Hexe zu sterben.\n\nBefreit mich aus diesem Käfig, dann kann ich uns beide in Sicherheit bringen. Hüter Odyn muss vor diesem schändlichen Verrat gewarnt werden!\n\nDie Schlundgebundene Kjellrun besitzt das Siegel, das mich befreien kann. Ihr findet diese schadenfrohe Schurkin gleich in der nächsten Halle.", sourceObjective = "Beschafft das helgeschmiedete Siegel von Kjellrun und befreit Danica aus der Gefangenschaft.", progress = "Ein solches Schicksal hat eine Val'kyr nicht verdient!", completion = "Ich werde allen von Euren edlen Taten erzählen, {name}. Was Ihr heute vollbracht habt, soll nie vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[63755] = { id = 63755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringliche Angelegenheit", description = "<Schlundgänger/Schlundgängerin>, es gibt eine dringliche Angelegenheit, der sich jemand annehmen muss.\n\nUnser Schicksalsschreiber wird vermisst. Er hat es noch nicht hierher geschafft. Eigentlich hätte er schon im Quorum des Suchers sein sollen, bevor...\n\n<Pfadschreiber Roh-Vess hält inne.>\n\nKönnt Ihr den Schicksalsschreiber suchen gehen? Viele Bediensteten nutzten die Höhlen in den Ruinen, um sich vor den Schlundgebundenen zu verstecken.", sourceObjective = "Sucht nach dem Schicksalsschreiber von Korthia.", completion = "Ihr sucht auch nach dem Schicksalsschreiber? Ich muss ihn finden. Unbedingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63756] = { id = 63756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung aus der Qual", description = "Die Schlundgebundenen töten jene, die sie im Quorum des Suchers finden, nicht einfach nur. Sie verhören die Überlebenden auch.\n\nWir sollten diejenigen retten, die noch zu retten sind. Womöglich hat einer von ihnen ja den Schicksalsschreiber gesehen.", sourceObjective = "Rettet 6 gepeinigte Bedienstete im Quorum des Suchers.", completion = "Es fällt mir schwer zu glauben, dass nicht ein einziger Bediensteter Informationen über den Verbleib des Schicksalsschreibers hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[63757] = { id = 63757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündert die Plünderer", description = "<Der Schlundgebundene hatte ein korthianisches Artefakt bei sich.\n\nEs ist nicht ersichtlich, was der Feind mit solchen Relikten zu tun gedenkt. Aber Ihr vermutet, die Bediensteten in der Zuflucht des Hüters hätten sie bestimmt gern zurück.>", sourceObjective = "Holt 4 korthianische Artefakte von den Schlundgebundenen zurück.", completion = "Eigenartig. Der Schicksalsschreiber verwendet solch ein Utensil für seine Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[63758] = { id = 63758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo man zuletzt nachsieht", description = "Ich kam in der Hoffnung hierher, den Schicksalsschreiber zu finden, oder zumindest etwas, das mir helfen könnte, ihn zu finden.\n\nDen Anzeichen nach war er hier und hat den Angriff der Schlundgebundenen überlebt. Der einzige Ort, an dem ich noch nicht gesucht habe, ist eine Meditationskammer auf der gegenüberliegenden Seite der Ruinen.\n\nIch kann mich nicht allein in das Quorum des Suchers wagen, das wäre zu gefährlich. Könntet Ihr mir nicht helfen?\n\nIch muss den Schicksalsschreiber finden. Es ist wirklich enorm wichtig.", sourceObjective = "Durchsucht das Quorum des Suchers nach dem vermissten Schicksalsschreiber.", completion = "Wirres Gerede und Räucherwerk. Die Hinweise sind schwach, aber es sind die einzigen, die wir haben.\n\nWir müssen das Refugium der Weisung durchsuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63759] = { id = 63759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuausrichtung der Suche", description = "Ich glaube, der Schicksalsschreiber war auf dem Weg zum Refugium der Weisung, einem heiligen Ort für die Bediensteten von Korthia.\n\nGlücklicherweise haben wir dank Eurer Gewohnheit, jedes Stück Unrat einzusammeln, das Ihr am Boden findet, das Utensil des Schicksalsschreibers gefunden!\n\nDas wird uns ganz sicher helfen, ihn zu finden. Aber zunächst müssen wir zum Refugium.", sourceObjective = "Trefft Verwalterin Kah-Than am Eingang zum Refugium der Weisung in Korthia.", completion = "{name}! Endlich!\n\nIhr wisst doch, dass ich das ohne Euch nicht schaffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[63760] = { id = 63760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos des Schicksals", description = "Die Verschlinger haben sich hier ausgebreitet, doch wir müssen uns darauf konzentrieren, den Schicksalsschreiber zu finden.\n\nBedienstete, die hier gebetet haben, haben an den Schreinen Animaopfer hinterlassen.\n\nDas Utensil, das Ihr gefunden habt, wird resonieren, wenn der Schicksalsschreiber in der Nähe war. Mit ein wenig Glück sollte uns das eine Vorstellung davon geben, wohin er gegangen sein könnte.", sourceObjective = "Lasst das Utensil des Schicksalsschreibers an den Schreinen im Refugium der Weisung resonieren.", completion = "Eine Illusion, um sich zu verbergen...\n\nDas nenne ich clever.", sourceObjectiveStatus = "unverified-source-field" }
quests[63761] = { id = 63761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzögerte Rache", description = "<Der korthianische Beschützer ist schwer verletzt und kann kaum sprechen.>\n\nVerschlinger... haben sich im Refugium ausgebreitet. Wir... waren zu wenige.\n\nMeine Pflicht... bleibt unerfüllt.\n\nDie Vorsehung... Ich...\n\n<Die Stimme des Beschützers wird immer schwächer.>", sourceObjective = "Tötet 10 Verschlinger im Refugium der Weisung.", completion = "<Ihr habt die Aufgabe des Beschützers erfüllt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[63762] = { id = 63762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Bann der Illusion", description = "Der Schicksalsschreiber hat die nötigen Gegenstände gesammelt, um in dieser Kammer eine Illusion zu erzeugen. Glücklicherweise können wir sein eigenes Utensil nutzen, um sie zu bannen und ihn zu enthüllen.\n\nEr wird ganz sicher dankbar sein, ein freundliches Gesicht zu sehen.\n\nIhr habt Euch bei dieser Aufgabe als unglaublich hilfreich erwiesen. Ohne Euch hätte ich es wirklich nicht geschafft.", sourceObjective = "Benutzt das Utensil des Schicksalsschreibers, um die Illusion zu bannen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63763] = { id = 63763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es könnte jeder sein", description = "<Die Fratze des immer noch warmen Kopfes des Schreckenslords Azodius starrt Euch an.\n\nDie Bediensteten in der Zuflucht des Hüters müssen über die Entführung des Schicksalsschreibers informiert werden.\n\nHochlord Fordragon wird zweifelsohne von dieser unerwarteten Bedrohung erfahren wollen.>", sourceObjective = "Bringt den Kopf von Azodius zu Bolvar Fordragon in der Zuflucht des Hüters.\n\nBereitgestellter Gegenstand:", completion = "Die Nachricht, dass die Nathrezim Korthia infiltrieren, ist zutiefst beunruhigend.\n\nWie lange sind sie schon hier? Welches Ziel verfolgen sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[63764] = { id = 63764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Griff nach dem Himmel", description = "Ich betrauere den Verlust meiner Schwestern und will nichts so sehr, wie ihren entsetzlichen Tod zu rächen. Aber ich weiß, dass ich der Magie der Hexe und ihrer Armee aus Schlundgebundenen nicht gewachsen bin.\n\nWir müssen uns von der Weisheit lenken lassen und von hier fliehen.\n\nIch bin zwar noch von der Gefangenschaft geschwächt, aber ich kann Euch von hier forttragen.\n\nVerschwinden wir, <mein Freund/meine Liebe>.", sourceObjective = "Fliegt mit Danica zu Odyns Hallen in der Himmelsfeste.", completion = "Willkommen in der Himmelsfeste, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63765] = { id = 63765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsichtbarer Held der Party", progress = "Oooh, das Buch sieht dick aus, das ist bestimmt sehr wichtig.", completion = "Das musstet Ihr jede Woche tun? Jetzt kümmere ich mich darum... und ich werde Euch nicht enttäuschen!" }
quests[63771] = { id = 63771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerung des Schicksals", description = "Schicksalsschreiber Roh-Tahl erwartet Euch in Oribos, solltet Ihr den Verlauf Eures Schicksals ändern wollen.\n\nIhr könnt jederzeit mit ihm sprechen.", sourceObjective = "Trefft Euch mit dem Schicksalsschreiber Roh-Tahl in Oribos, wenn Ihr den Fäden des Schicksals folgen möchtet.", completion = "Ihr seid zurück, Sterblicher.\n\nWünscht Ihr, Euer Schicksal zu ändern?", sourceObjectiveStatus = "unverified-source-field" }
quests[63772] = { id = 63772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beflügelte Belagerung", description = "Truppen der Kyrianer sind eingetroffen, um den Angriff zu unterstützen. Sie haben unsere Flanke gesichert und werden das Südtor der Verdammnisfestung belagern.\n\nMeldet Euch bei Artemede und helft den Kyrianern nach besten Kräften!", sourceObjective = "Unterstützt Artemede und die kyrianischen Streitkräfte außerhalb des Südtors der Verdammnisfestung.", completion = "Eure Anwesenheit hier gibt uns neue Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63773] = { id = 63773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr und welche Armee?", description = "Der Kerkermeister hat eine Streitkraft aus Elitesoldaten entsandt, um unseren Truppen in den Rücken zu fallen. Dieser Angriff bringt unsere gesamte Operation in Gefahr!\n\nIhr müsst den Feind zusammen mit einem weiteren Soldaten eliminieren. Aus jedem der fünf Häuser von Maldraxxus hat ein Freiwilliger darum gebeten, Euch unterstützen zu dürfen, {name}.\n\nWählt einen dieser Freiwilligen aus und lasst ihm die Ehre zuteilwerden, an Eurer Seite zu dienen.", sourceObjective = "Wählt einen Champion aus und eliminiert 3 schlundgefesselte Amokläufer und 5 schlundgefesselte Verwüster.", completion = "Der Sieg wird unser sein, Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[63774] = { id = 63774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenfänger von Maldraxxus", sourceObjective = "Bringt 4 körperlose Seelen zu Frontlinienflickern, damit sie ihnen neue Körper anfertigen können.", completion = "Die Arbeit eines maldraxxischen Soldaten endet nie!", sourceObjectiveStatus = "unverified-source-field" }
quests[63775] = { id = 63775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kryptogramme und Schlüssel", description = "Die Kammern des Wissens in Korthia sind durch vielschichtige Sicherheitsmaßnahmen geschützt, aus gutem Grund.\n\nFür jedes Archiv benötigt man verschiedene Kryptografen, um die Barrieren zu entschlüsseln und auszuschalten. Sie sind, in Ermangelung eines besseren Ausdrucks, die Schlüssel zu allen Geheimnissen.\n\nSucht außerhalb des Archivs nach Kryptografen, die von den Schlundgebundenen gestohlen wurden, und bringt sie mir zurück. Ich werde dafür sorgen, dass sie, und damit auch die Geheimnisse, die sie schützen, nicht in falsche Hände fallen.", sourceObjective = "Bringt 6 gestohlene Kryptografen aus der Umgebung des Archivs und vom Quorum des Suchers zurück.", progress = "Wir können nicht zulassen, dass der Kerkermeister die Archive Korthias plündert.", completion = "Ich bin Euch sehr dankbar, dass Ihr geholfen habt, unsere Geheimnisse vor dem Kerkermeister zu verbergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63776] = { id = 63776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtungsdaten", description = "Ich grüße Euch, <Schlundgänger/Schlundgängerin>. Habt Ihr einen Moment Zeit?\n\nWie Ihr sicher wisst, hat mein Kartell insgeheim Beobachtungsgeräte über ganz Korthia verteilt. Aber diese Daten nützen uns nichts, wenn sie nicht abgerufen werden. Und genau da kommt Ihr ins Spiel.\n\nDie Aufzeichnungen in der Höhle des Gelehrten sollten zur Abholung bereit sein. Die Geräte selbst werdet Ihr nicht sehen können, aber die Daten erscheinen Euch als hell leuchtende Kugel.\n\nUnd schaut unbedingt auch in den unterirdischen Höhlen nach!\n\nWenn Ihr mir diese Daten bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Beschafft 5 Beobachtungsdaten aus der Höhle des Gelehrten.", progress = "Habt Ihr die Beobachtungsdaten aus der Höhle des Gelehrten beschafft?", completion = "Die Höhle des Gelehrten muss ein ganz anderer Ort gewesen sein, bevor die Ketten des Kerkermeisters sie zerstört haben. Jetzt ist sie jedenfalls kein Refugium für intellektuelles Streben mehr.\n\nDiese Informationen sind extrem wertvoll für uns. Hier ist wie versprochen Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63777] = { id = 63777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelte Geheimnisse", description = "Ah, Korthia. Was für Geheimnisse werden wir offenlegen?\n\nMeine Partner haben hart daran gearbeitet, in diesem verheerten Land verschiedene kleinere Gegenstände von Interesse aufzuspüren und sicherzustellen. Nichts von großer Bedeutung, kann ich Euch versichern.\n\nSie haben diese Gegenstände in dafür vorgesehenen Behältern gesichert, die nun in der Höhle des Gelehrten zur Abholung bereitstehen. Aber keine Sorge: Sie sind mit einem undurchdringlichen Siegel verschlossen, um sowohl den Inhalt als auch den Zusteller zu schützen.\n\nWenn Ihr mir diese versiegelten Behälter bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Beschafft 5 versiegelte Behälter aus der Höhle des Gelehrten.", progress = "Habt Ihr die versiegelten Behälter?", completion = "Wunderbar! Ihr habt alles mitgebracht, um das ich gebeten habe.\n\nMacht Euch wie gesagt keine Sorgen um den Inhalt dieser Behälter. Er stellt keine Gefahr für Euch dar.\n\nHier ist Eure versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63778] = { id = 63778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht voran", description = "Es bricht mir das Herz, ein weiteres Land völlig ausgelöscht zu sehen. Ich kann mir gut vorstellen, wie schön Korthia einmal gewesen sein muss.\n\nAber wir dürfen nicht dem hinterhertrauern, was wir verloren haben. Ara'lon hat mich gelehrt, dass wir nicht untätig verharren müssen.\n\nWir können uns für den Kampf entscheiden.\n\nIhr könnt uns helfen, indem Ihr Anima von den Schlundgebundenen zurückholt. Dadurch wären wir in der Lage, unsere eigenen Streitkräfte und Verteidigungen aufzubauen.", sourceObjective = "Sammelt 8 geplünderte Anima in der Höhle des Gelehrten in Korthia.", progress = "Ich freue mich auf eine Zeit, in der wir nicht mehr ständig ums Überleben kämpfen müssen.", completion = "Ich danke Euch.\n\nJedes bisschen Anima, das wir sammeln, gibt mir Hoffnung, dass wir die Schattenlande heilen können. Eines Tages wird alles wieder ganz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63779] = { id = 63779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anschein von Normalität", sourceObjective = "Sammelt 6 Schreinopfergaben.", progress = "Wie geht es Euch? Ich habe gehört, dass das Refugium der Weisung von Verschlingern überrannt wurde.", completion = "Das ist wunderbar. Wir werden sie den Bediensteten geben, damit sie wieder ihre Rituale durchführen können. Es ist wichtig, Handlungen zu unterstützen, die uns Frieden bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63780] = { id = 63780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal sehen, wie ihnen DAS gefällt!", description = "Allein der Gedanke daran, wie die Truppen des Kerkermeisters in den Ardenwald eingedrungen sind, macht mich zornig!\n\nUnd wenn ich zornig bin, benötige ich einen Ausgleich.\n\nUnd am besten wäre es, wenn Ihr mir helft, diesen Ausgleich zu erlangen! Tötet die Schlundgebundenen und bringt mir ihre Embleme, um mir zu zeigen, wie viele ihr getötet habt.\n\nEs ist mir vollkommen egal, woher Ihr sie bekommt, solange sie von diesen schlundgebundenen Würmern stammen!", sourceObjective = "Sammelt 12 Embleme der Schlundgebundenen.", progress = "Die Schlundgebundenen werden kriegen, was sie verdienen!", completion = "So viele Embleme! Das macht mich sehr glücklich.\n\nNatürlich wird alles erst dann wirklich besser, wenn wir den Kerkermeister persönlich kriegen, aber das hier reicht vorläufig völlig aus.\n\nIch danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[63781] = { id = 63781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtpläne der Schlundgebundenen", description = "Was würde dem Feind wohl größeren Schaden zufügen: Wenn wir einen Teil ihrer Truppen vernichten oder ihre Kommunikation unterbinden?\n\nOder besser noch: Wie wäre es, wenn Ihr mithilfe dieser Kommunikation Eure Truppen perfekt platzieren könntet, um ihre Verstärkung zu überfallen?\n\nIch sehe, Ihr versteht, wovon ich spreche. Voxiferus, ein Leutnant der Schlundgebundenen, wird über die nördliche Straße vom Schlund nach Korthia reisen. Findet und tötet ihn, und bringt mir ihre Schlachtpläne.", sourceObjective = "Beschafft die Schlachtpläne der Schlundgebundenen.", progress = "Habt Ihr den Leutnant gefunden und besiegt?", completion = "Und wieder einmal habt Ihr überlebt. Ihr erinnert mich an mich selbst. Ich werde mir diese Pläne anschauen und unsere Verbündeten informieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63782] = { id = 63782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlundgebundene Rituale", description = "Die Schlundgebundenen verfügen über zahllose Anwender von Magie in ihren Reihen. Wir wissen nichts über diese Magie und genau das macht sie so tödlich.\n\nUm unsere Verteidigung gewissenhaft vorzubereiten, müssen wir mehr über sie erfahren. Meine persönliche Neugier bezüglich ihrer Methoden und Rituale ist dabei sekundär.\n\nMacht Jagd auf diese gefährlichen Zauberwirker und bringt mir ihre Zauberfolianten.", sourceObjective = "Beschafft 8 Zauberfolianten der Schlundgebundenen.", progress = "Seinen Gegner zu kennen, ist eine mächtige Waffe.", completion = "Darin sind sehr gefährliche und üble Informationen enthalten. Aber wir schützen uns vor dem Feind, indem wir wissen, wozu er fähig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63783] = { id = 63783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animarücknahme", description = "Für unseren Einsatz hier brauchen wir konstanten Nachschub an Truppen, Vorräten und Anima. Letztere zu besorgen, gestaltet sich augenscheinlich am schwierigsten, aber ich habe einen gewissen Einfallsreichtum entwickelt.\n\nIn der Nähe gibt es eine üppige Quelle an Anima: die Verschlinger, die gerade das Refugium der Weisung überrennen. Das ist nicht so leicht, wie sie einer Seele zu entreißen, aber genauso effektiv. Zumindest wenn man stark genug ist. Seid Ihr das?", sourceObjective = "Gewinnt 8 verschlungene Anima von den Verschlingern im Refugium der Weisung zurück.", progress = "Jeder Tropfen Anima, den wir zurückgewinnen können, ist eine potenzielle Waffe gegen den Kerkermeister.", completion = "Ihr könnt mir diese Anima anvertrauen. Ich werde dafür sorgen, dass sie gegen den Kerkermeister und seine Truppen eingesetzt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[63784] = { id = 63784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold spielt keine Rolle", sourceObjective = "Beschafft 7 graubraune Gromits.", completion = "Jetzt sieh sich einer die kleinen Häschen an. Mit der Tarnung kann man die im Wald gar nicht sehen. Wie praktisch ist das denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[63785] = { id = 63785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Anstrengungen: Quorum des Suchers", description = "Die Angriffe von Zovaals Truppen fügen dem Land weiterhin verheerenden Schaden zu.\n\nWir müssen ihnen eine Lektion erteilen. Zeigt ihnen, dass wir nicht zurückweichen, {name}.\n\nDie Macht des Ardenwalds wird Euch beistehen.", sourceObjective = "Schlagt die Truppen des Kerkermeister beim Quorum des Suchers in Korthia zurück.", completion = "Das war eine beeindruckende Vorstellung, {name}.\n\nDas sollte uns etwas Zeit verschaffen, unsere Klingen vor der nächsten Schlacht zu schärfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63786] = { id = 63786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf den Windgepeitschten Nistgipfel", description = "Der Himmel über Korthia ist ein gefährlicher Ort.\n\nNicht nur die Schlundgebundenen bedrohen unsere Streitkräfte, sondern auch die einheimischen Geschöpfe, die unglaublich feindselig sind. Wir müssen den Luftraum für unsere eigenen geflügelten Verbündeten und Tiere sichern.\n\nDie einheimischen flugfähigen Geschöpfe stammen vom Windgepeitschten Nistgipfel. Begebt Euch dorthin und beseitigt alle aggressiven Lebewesen in der Luft.\n\nDas wird uns die Luftüberlegenheit sichern.", sourceObjective = "Reist zum Windgepeitschten Nistgipfel und befreit das Gebiet von feindlichen Kreaturen.", completion = "Ausgezeichnete Arbeit, Schlundgänger. Wenn wir den Windgepeitschten Nistgipfel unter Kontrolle haben, haben unsere fliegenden Verbündeten eine Chance, den Luftraum zu beherrschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63787] = { id = 63787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Anstrengungen: Zerfleischerausguck", description = "Meine Augen haben mir verraten, dass sich nahe der neuen Straße vom Schlund nach Korthia ein Ort namens Zerfleischerausguck befindet. Diese Position würde uns einen strategischen Vorteil verschaffen.\n\nLeider wurde das Gebiet von Splitterfellen überrannt.\n\nWenn es uns gelingt, dieses Gebiet zu sichern, haben wir nicht nur freie Bahn nach Westen, sondern auch einen Beobachtungspunkt, um die Truppen des Kerkermeisters zu überwachen.", sourceObjective = "Befreit den Zerfleischerausguck von den Splitterfellen.", completion = "Der strategische Vorteil, den wir nun gegenüber den Truppen des Kerkermeisters genießen, ist ein bedeutender Etappensieg. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63788] = { id = 63788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Anstrengungen: Refugium der Weisung", description = "Der Kerkermeister hat das Zuhause der Bediensteten zerstört, aber wir können sie in diesen schwierigen Zeiten unterstützen.\n\nGanz in der Nähe befindet sich das Refugium der Weisung. Sie verehren diesen Ort und sind sehr traurig über den gegenwärtigen Zustand. Normalerweise begeben sie sich dorthin, um zu beten und nach der Wahrheit zu suchen, aber jetzt haben die Verschlinger das Refugium übernommen.\n\nErledigt die Verschlinger dort, damit das Refugium der Weisung wieder ein Ort der Rituale und Gebete sein kann.", sourceObjective = "Befreit das Refugium der Weisung von den Verschlingern.", completion = "Ich danke Euch, Schlundgänger. Ich bin mir sicher, dass die Bediensteten mit großer Freude und Erleichterung vernehmen werden, dass sie an ihren heiligen Ort zurückkehren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[63789] = { id = 63789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Anstrengungen: Höhle des Gelehrten", description = "Wir können nicht zulassen, dass die Schlundgebundenen so nahe an unserem eigenen Lager Stellung beziehen. Die Bediensteten sagen, sie würden unseren Unterschlupf gut verborgen halten, aber ich finde keine Ruhe, solange ich den Feind mit eigenen Augen sehen kann.\n\nBegebt Euch in die Höhle des Gelehrten und vertreibt die Schlundgebundenen von dort.", sourceObjective = "Befreit die Höhle des Gelehrten von Schlundgebundenen.", completion = "Ihr habt diese Aufgabe bewundernswert erfüllt, Schlundgänger. Wir danken Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[63790] = { id = 63790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlerkopfgeld: Lord Azzorak", description = "Ein mächtiger Schreckenslord namens Lord Azzorak ist dem Kartell in Korthia ein großer Dorn im Auge.\n\nWer auch immer dieses Übel beseitigt, erhält eine fürstliche Belohnung.\n\nSeid vorsichtig. Azzorak ist sehr mächtig. Ihr benötigt vielleicht mehrere Verbündete, um ihn zu besiegen.", sourceObjective = "Besiegt Lord Azzorak.", completion = "Dank Euch wird Lord Azzorak das Kartell Xy hier in Korthia nicht länger behindern.\n\nIch danke Euch auch persönlich, Schlundgänger. Euch steht eine große Zukunft bevor.\n\nNehmt bitte diese Belohnung als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[63791] = { id = 63791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlerkopfgeld: Valdinar der Fluchgeborene", description = "Ein mit Stacheln bewehrter Schlundgebundener namens Valdinar der Fluchgeborene ist dem Kartell in Korthia ein großer Dorn im Auge.\n\nWer auch immer dieses Übel beseitigt, erhält eine fürstliche Belohnung.\n\nSeid vorsichtig. Valdinar ist sehr mächtig. Ihr benötigt vielleicht mehrere Verbündete, um ihn zu besiegen.", sourceObjective = "Besiegt Valdinar den Fluchgeborenen.", completion = "Dank Euch wird Valdinar der Fluchgeborene das Kartell Xy hier in Korthia nicht länger behindern.\n\nIch danke Euch auch persönlich, Schlundgänger. Euch steht eine große Zukunft bevor.\n\nNehmt bitte diese Belohnung als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[63792] = { id = 63792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlerkopfgeld: Nocturnus der Auflöser", description = "Ein niederträchtiger Schlundmagus namens Nocturnus der Auflöser ist dem Kartell in Korthia ein großer Dorn im Auge.\n\nWer auch immer dieses Übel beseitigt, erhält eine fürstliche Belohnung.\n\nSeid vorsichtig. Nocturnus ist sehr mächtig. Ihr benötigt vielleicht mehrere Verbündete, um ihn zu besiegen.", sourceObjective = "Besiegt Nocturnus den Auflöser.", completion = "Dank Euch wird Nocturnus der Auflöser das Kartell Xy hier in Korthia nicht länger behindern.\n\nIch danke Euch auch persönlich, Schlundgänger. Euch steht eine große Zukunft bevor.\n\nNehmt bitte diese Belohnung als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[63793] = { id = 63793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlerkopfgeld: Ensydius der Schänder", description = "Ein geflügelter Schlundgebundener namens Ensydius der Schänder ist dem Kartell in Korthia ein großer Dorn im Auge.\n\nWer auch immer dieses Übel beseitigt, erhält eine fürstliche Belohnung.\n\nSeid vorsichtig. Ensydius ist sehr mächtig. Ihr benötigt vielleicht mehrere Verbündete, um ihn zu besiegen.", sourceObjective = "Besiegt Ensydius den Schänder.", completion = "Dank Euch wird Ensydius der Schänder das Kartell Xy hier in Korthia nicht länger behindern.\n\nIch danke Euch auch persönlich, Schlundgänger. Euch steht eine große Zukunft bevor.\n\nNehmt bitte diese Belohnung als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[63794] = { id = 63794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlerkopfgeld: Hungriger Behemoth", description = "Neue Länder bieten neue Möglichkeiten. Wer uns eine beträchtliche Menge Verschlingerblut, am besten von einem Behemoth, bringen kann, erhält von uns im Gegenzug eine Anzahl wertvoller Gegenstände.\n\nZaghafte Sammler brauchen sich nicht zu bewerben.\n\nBringt bitte diese Probe zu Ta'nasi in der Zuflucht des Hüters.", sourceObjective = "Beschafft eine beträchtliche Menge Verschlingerblut von einem hungrigen Behemoth.", progress = "Habt Ihr etwas zum Tauschen?", completion = "<Ta'nasi hält die Probe hoch in den Himmel.>\n\nEine ausgezeichnete Probe. Das reicht vollkommen.\n\nWie versprochen, hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63810] = { id = 63810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt ein Vogel geflogen", description = "Ich habe im Schlund viele schwarze Schwingen gesehen, aber niemals welche mit goldenem Glanz.\n\nDa die Auralsequenzierer jetzt die Informationen verlässlich übertragen, sollten wir die Quelle dieser Federn ausfindig machen können.\n\nFolgt der Spur, <Schlundgänger/Schlundgängerin>. Hier wartet ein Geheimnis auf uns. Und vielleicht auch Profit.\n\nGold genießt doch dort, von wo Ihr herkommt, einen gewissen Wert, nicht wahr?", sourceObjective = "Folgt der Spur der goldenen Federn, um herauszufinden, wer sie verloren hat.", completion = "Es tut meinem Herzen gut, endlich ein edles Gesicht in diesem alptraumhaften Reich zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63811] = { id = 63811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine reine Hassbeziehung", description = "Als die erste meiner Schwestern verschwand, waren wir besorgt. Die, die wir ausgesandt haben, um sie zu finden, kehrten nicht zurück. Und der nächste Suchtrupp auch nicht.\n\nWas wir hier aufgedeckt haben, ist ein furchtbarer Verrat von jemanden, dem wir einst vertrauten.\n\nKommt, wir müssen Odyn berichten, was wir im Schlund gesehen haben.\n\nSein Zorn wird fürchterlich sein.", sourceObjective = "Begleitet Danica zur Großen Methalle und berichtet Odyn, was Helya getan hat.", progress = "Ich gebe nicht dem Boten die Schuld an einer Nachricht, {name}.", completion = "Helya ist zu weit gegangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[63822] = { id = 63822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyrangriff" }
quests[63823] = { id = 63823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtfaeangriff", description = "Unser Angriff hat die Truppen des Kerkermeisters überrumpelt. Wir werden die Verdammnisfestung überrennen und seine Champions am Altar der Herrschaft besiegen!\n\nWir brauchen Eure Hilfe, <Schlundgänger/Schlundgängerin>. Unterstützt unsere Soldaten auf dem Schlachtfeld!", sourceObjective = "Schließt 1 Quests in der Verdammnisfestung und im Antlitz des Vergessens ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[63824] = { id = 63824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrianerangriff", description = "Unser Angriff hat die Truppen des Kerkermeisters überrumpelt. Wir werden die Verdammnisfestung überrennen und seine Champions am Altar der Herrschaft besiegen!\n\nWir brauchen Euch, <Schlundgänger/Schlundgängerin>. Unterstützt unsere Soldaten auf dem Schlachtfeld!", sourceObjective = "Schließt 1 Quests in der Verdammnisfestung und im Antlitz des Vergessens ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[63827] = { id = 63827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ermutigende Worte", description = "Schon seit Stunden kämpfen unsere Streitkräfte unerbittlich. Zweifelsohne sind sie erschöpft und entmutigt.\n\nNehmt diesen Kodex und tragt den Truppen Texte daraus vor. Lasst Euch nicht täuschen: Die Worte mögen Euch bedeutungslos erscheinen, doch in ihnen steckt große Macht.\n\nWenn unsere erschöpften Beschützer sie hören, werden sie daraus Kraft und neue Hoffnung schöpfen.", sourceObjective = "Rezitiert die Worte des Kodex vor 8 erschöpften Beschützern.", completion = "Ihr wart unseren Truppen eine große Hilfe. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63828] = { id = 63828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meiner ist größer", description = "Der Kerkermeister setzt eine große Zahl neu geschmiedeter Konstrukte ein, um unsere Truppen aufzuhalten. Glücklicherweise bin ich auf diese Möglichkeit bestens eingestellt.\n\nIch habe unseren größten Zenturio bereit gemacht, um diese Bedrohung abzuwehren.\n\n<Schlundgänger/Schlundgängerin>, bitte steuert unseren Zenturio in die Schlacht.", sourceObjective = "Nutzt den Zenturioverwüster, um die Konstrukte des Kerkermeisters auszuschalten.", progress = "Haben wir ihre Konstrukte zurückgedrängt?", completion = "Die Streitkräfte des Kerkermeisters sind endlos und unsere Zahlen eher gering, doch mit Eurer Hilfe werden wir erfolgreich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[63829] = { id = 63829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier unten schwebt niemand", description = "Nun kommt unsere Chance, jene zu befreien, die wir bereits verloren geglaubt hatten!\n\nViele unserer Aspiranten wurden vom Kerkermeister ergriffen, um sie in seine Armee zu zwingen. Jene, die sich ihm widersetzt haben, wurden in die über uns schwebenden Käfige gesperrt, wo sie bleiben sollen, bis ihre Seelen gebrochen sind.\n\nZerschmettert die Ketten der Herrschaft und befreit die gefangenen Aspiranten aus den Käfigen.", sourceObjective = "Rettet 8 gefangene Aspiranten.", completion = "Eure Taten haben die Reinheit Eurer Seele unter Beweis gestellt. Artemede und ich würden jederzeit an Eurer Seite kämpfen, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[63831] = { id = 63831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Instrument des Zorns", description = "Ich werde diesen Angriff auf meine Val'kyr vergelten, und zwar mit unerbittlichem Zorn!\n\nEuch kommt dabei eine wichtige Rolle zu, {class}. Ihr müsst den Mut aufbringen, den Ihr heute bewiesen habt, um mein Auge in die Schlacht zu locken.\n\nAber zunächst wartet eine einfachere Aufgabe auf Euch... die Erschaffung des Horns, das meinen Zorn heraufbeschwören wird. Meisterschmied Helgar wird Euch anleiten.", sourceObjective = "Helft Meisterschmied Helgar an der Schmiede von Odyn.", progress = "Wo ist das Horn, das Ihr geschmiedet habt?", completion = "Da habt Ihr gute Arbeit geleistet, {name}.\n\nUnd natürlich erhält jedes gute Horn einen Namen! So will es unsere Tradition!", sourceObjectiveStatus = "unverified-source-field" }
quests[63833] = { id = 63833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror im Tremaculum", description = "Ich bin sicher, meine Verbündeten und die Generäle haben spezifischere Aufgaben für Euch.\n\nMeine Bitte dagegen ist recht simpel. Derzeit sind wir auf allen Seiten von Feinden umzingelt.\n\nDrängt sie zurück und verschafft uns etwas Freiraum.", sourceObjective = "Tötet 30 Feinde im Tremaculum.", completion = "Heute können wir die Streitkräfte des Kerkermeisters vielleicht noch nicht besiegen, doch alles hat irgendwann ein Ende.\n\nSogar das Böse.", sourceObjectiveStatus = "unverified-source-field" }
quests[63834] = { id = 63834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen des Tremaculums", description = "Die Venthyr von Sündensturz verschwenden keine Seelen, und ihre Steingeborenen verschwenden keine Waffen.\n\nHolt Euch die Werkzeuge unseres Feindes, auf dass sie unsere Armeen stärken.", sourceObjective = "Sammelt 6 schlundgebundene Waffen, 6 grausige Kronen und 6 Schemenaugen.", progress = "Jede Waffe kann in den Dienst gezwungen werden.", completion = "Nur wenige Waffen sind von Natur aus gut oder böse. Diese Bürde obliegt ihrem Träger.", sourceObjectiveStatus = "unverified-source-field" }
quests[63835] = { id = 63835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Festherolds", sourceObjective = "Helft Temel, dem Festherold, Giftbomben auf 50 Gegner im Tremaculum zu werfen.", completion = "Ha! Ich vermute, dem Kerkermeister ist nie in den Sinn gekommen, sich auf einen Angriff des Festherolds vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63836] = { id = 63836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahnbrechers Fanclub", description = "Zahnbrecher ist der stärkste Gräber aller Zeiten! Er ist unglaublich!\n\nEr ist da unten am großen Torghastportal und zerrt die Bösewichte einfach aus ihrer Heimat raus!\n\nMeist haben die nicht mal 'ne Ahnung, was überhaupt passiert, ha ha!\n\nIch und Knüppelfratze sind seit unserer Ankunft hier in seinem Fanclub.\n\nWollt Ihr auch beitreten? Das Beitrittsritual ist ganz einfach: Geht da runter und verprügelt, was auch immer er aus dem Portal holt!", sourceObjective = "Tötet 12 Gegner aus Torghast, die Zahnbrecher aus dem Portal gezogen hat.", completion = "Ihr habt Euch auch Zahnbrechers Fanclub angeschlossen? Genau wie Lady Mondbeere.\n\n<Prinz Renathal überlegt einen Moment.>\n\nIch habe Rendels Einladung zwar abgelehnt, aber vielleicht sollte ich das noch einmal überdenken...", sourceObjectiveStatus = "unverified-source-field" }
quests[63837] = { id = 63837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tee für jede Gelegenheit", sourceObjective = "Helft Tubbins und Gubbins dabei, Tee zu 15 Verbündeten im Tremaculum zu bringen.", completion = "Tubbins hat versprochen, mir eine Tasse für unsere Siegesfeier am Gluthof aufzuheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63838] = { id = 63838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung der Duellantin", sourceObjective = "Bittet Schock den Schicken, Euch auf das Bollwerk zu werfen, und kämpft dann gegen die Champions der Armee der Schlundgebundenen.", completion = "Nadjia hat im Alleingang einen ganzen Trupp von Schlundgebundenen abgewehrt, während die Gräber unsere Basis errichtet haben.\n\nSelbst General Draven war davon beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63839] = { id = 63839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon eine einzige würdige Seele", description = "Ich habe mit eigenen Augen gesehen, wie würdige Seelen zu Unrecht in den Schlund gestoßen wurden.\n\nDer Diener des Obersten Kämmerers hätte fast auch den armen Gresit hier hineingeworfen. Unter meiner Obhut hat er sich mehr als bewährt.\n\nSeht Euch unter den Seelen um, die der Abschaum des Kerkermeisters für \"unwürdig\" hält. Untersucht bei jeder einzelnen ganz genau, ob sie ihr Schicksal hier auch verdient hat.\n\nAuch wenn wir alle Seelen im Tremaculum untersuchen müssen und nur eine einzige würdige Seele finden, die wir mit zurück nach Revendreth nehmen können, war es die ganze Mühe wert.", sourceObjective = "Untersucht unwürdige Seelen im Tremaculum, bis Ihr eine wahrhaft würdige Seele findet.", completion = "Auch in den Tiefen des Schlundes versucht die Anklägerin noch, jede Seele zu retten...\n\nEs inspiriert mich immer wieder, wie sie sich für Revendreths wahre Vorsehung aufopfert.", sourceObjectiveStatus = "unverified-source-field" }
quests[63840] = { id = 63840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So schnell werden sie groß", description = "Ich weiß schon, was Ihr denkt, aber ich habe diese Gormlinge absolut unter Kontrolle!\n\nIch habe am Gluthof der Venthyr das eine oder andere darüber gelernt, wie man diese Unruhestifter in Schach hält und kontrolliert.\n\nWenn Ihr ihre Kraft nutzen möchtet, um uns im Kampf zu helfen, dann leihe ich Euch meinen Stab. Ihr könnt damit einen Gormling aussuchen und ihm befehlen, die Leichen unserer Feinde zu fressen, um größer und stärker zu werden.\n\nViele Leichen wird es dazu übrigens nicht brauchen. Gormlinge wachsen schnell.", sourceObjective = "Lasst einen Gormling wachsen, indem Ihr ihm Leichen verfüttert, und reitet auf ihm zum Sieg!", progress = "Falls Ihr Euren Gormling verloren habt, hat Niya oben auf dem Wall ihn sicher gefunden.", completion = "Ich werde den Gorm hier festhalten, bis er gebraucht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[63841] = { id = 63841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Himmelsjagd", description = "Die Luftangriffe machen Schock dem Schicken und den anderen großen Gräbern schwer zu schaffen.\n\nDen Gräbern können sie sich vielleicht entziehen, aber niemand entkommt der Wilden Jagd.\n\nNehmt meinen Speer und zerrt die Schlundgebundenen im Himmel über der Westlichen Brücke zu Boden.\n\nSobald sie einmal am Boden sind, könnt Ihr sie mit Leichtigkeit erledigen.\n\nMeine Fallensteller werden sie für Euch etwas aufhalten.", sourceObjective = "Zieht mit Korayns Speer 8 schlundgebundene Himmelslauerer auf den Boden und tötet sie.", completion = "Ich danke Euch, {name}. Ohne unsere Lulatschgräber kämen die Truppen hier kein Stück vorwärts.", sourceObjectiveStatus = "unverified-source-field" }
quests[63842] = { id = 63842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist 'n guter Trick", description = "Diese grausamen Peiniger machen mich so wütend...\n\nWeil niemand sie in die Schranken weist, quälen die Fieslinge des Kerkermeisters gute Seelen, die grundlos hierhergeschickt wurden!\n\nAber jetzt bin ich da, und ich habe den perfekten Plan, um sie dafür zu bestrafen.\n\nWas meint Ihr? Wollt Ihr mir helfen, den Spieß umzudrehen?", sourceObjective = "Schrumpft im Tremaculum 15 Gegner und vergrößert 4 Schlundratten, damit diese sie fressen!", progress = "Wenn Lady Mondbeere das für klug hält...", completion = "Langweilig ist es zumindest nie, wenn Lady Mondbeere mit von der Partie ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63843] = { id = 63843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz und Seele", description = "Die Verschmähten, die dem Kerkermeister dienen, beherrschen die Lüfte über uns, doch wir kennen ihre Schwäche und werden sie uns zunutze machen.\n\nUnter meiner Leitung hat Mikanikos einige Speere des wahrhaftigen Herzens für unsere Beschützer gefertigt. Wenn die Schlundgebundenen mit diesen Speeren getroffen werden, schwächt sie das, denn ihre Seele wird offengelegt und sie müssen sich ihrem wahren Ich stellen.\n\nSammelt die Speere des wahrhaftigen Herzens, um mit ihnen die über uns fliegenden schlundgebundenen Myrmidonen zu bezwingen.", sourceObjective = "Sammelt 6 Speere des wahrhaftigen Herzens und besiegt 6 schlundgebundene Myrmidonen.", completion = "Dieser Sieg bringt viel Trauer mit sich, doch es musste vollbracht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[63844] = { id = 63844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wenigen Auserwählten", description = "Ich brauche noch mehr Val'kyr, die Danica in der kommenden Schlacht unterstützen. {name}, Euch wird die Ehre zuteil, die Würdigsten auszuwählen.\n\nDie stärksten werden sich der Herausforderung im Zirkel des Ruhms stellen. Kämpft hart, {class}, und gereicht Euren Waffen zur Ehre.", sourceObjective = "Geht zum Zirkel des Ruhms und kämpft gegen die Val'kyr, um die Würdigsten unter ihnen zu finden.", progress = "Sind die Würdigen erwählt?", completion = "Gut gekämpft. Kolfinna, Dyrfinna und Aeskir haben sich der Herausforderung gestellt und erwarten Euch in Odyns Hallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63845] = { id = 63845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odyns Zorn", description = "Das Horn wurde geschmiedet und die Würdigen sind ausgewählt.\n\nUnd jetzt, {name}, müssen wir nur noch die von mir auserwählten Val'kyr an das Horn binden und sie mit meinen Kräften verstärken, damit sie mit der Macht meines Zorns zuschlagen können.\n\nKommt und seht.", sourceObjective = "Wohnt der Ermächtigung der auserwählten Val'kyr und der Bindung des Ilskahorns bei.", progress = "Ja? Hattet Ihr eine Frage?", completion = "Es ist vollbracht. Danica und ihre Schwestern sind von meiner Macht durchdrungen und tragen nun meinen Zorn in sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[63846] = { id = 63846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Glutsammelhof", description = "Theotar ist zweifelsohne brillant, aber viele übersehen die Genialität seiner Gräberhelfer Gubbins und Tubbins.\n\nSeht Ihr den Bergkamm hinter uns? Die Schmieden des Kerkermeisters dort drüben spucken Seelenstahlglut aus.\n\nMit einem Spiegel aus dieser Glut könnten wir vieles erreichen...\n\nGubbins hat bereits einen speziellen Sonnenschirm angefertigt, der seinen Träger vor der herabfallenden Glut schützen kann.\n\nTrefft ihn bei den Schmieden und beschafft ein paar Stücke dieser Seelenstahlglut!", sourceObjective = "Tötet 4 wütende Schmiedesplitter und sammelt 4 Stücke Seelenstahlglut.", progress = "Habt Ihr die Glut beschafft?", completion = "Verkohlte Splitter! Daraus werden wir ein paar ausgezeichnete Spiegel fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63848] = { id = 63848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen der Dankbarkeit", description = "Eure Anwesenheit hier erfüllt eine alte Prophezeiung, <Schlundgänger/Schlundgängerin>. Ich bin mir sicher, dass Ihr und Eure Verbündeten uns retten werdet.\n\nVielleicht fiel mein Urteil über Eure Mittlerfreundin zu hart aus. Immerhin hat sie Euch nach Korthia begleitet.\n\nBitte richtet Ve'nari unseren Dank aus und lasst sie wissen, dass wir gerne ihre Fragen beantworten werden.\n\nSie... scheint eine ganze Reihe davon zu haben.", sourceObjective = "Sprecht mit Ve'nari in der Zuflucht des Hüters in Korthia.", completion = "Ein Dankeschön ist höflich.\n\nEin Gefallen ist besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[63849] = { id = 63849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hörhilfe", description = "Was für ein Glück! Ihr wurdet an einen Ort teleportiert, an dem ich ein gewisses... Interesse habe. Platziert die Auralsequenzierer, die ich Euch gegeben habe, dann werde ich versuchen, ein brauchbares Signal aufzubauen.\n\nEin dermaßen gefährlicher Ort wird oberste Diskretion erfordern. Ihr solltet Eure ätherische Verschleierung benutzen, um nicht entdeckt zu werden.", sourceObjective = "Platziert die Auralsequenzierer in Desmotaeron, um Ve'nari dabei zu helfen, die Einwohner zu belauschen.", completion = "Perfekt. Ihre Geheimnisse gehören bald mir.\n\nVerzeihung. Ich meinte \"uns\".", sourceObjectiveStatus = "unverified-source-field" }
quests[63850] = { id = 63850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgung - Kleine Konsolen" }
quests[63853] = { id = 63853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flamme auslöschen", description = "Könnt Ihr ihn sehen? \n\nAus dem Augenwinkel, die ganze Zeit... hell glühend!\n\nWie soll man sich denn entspannen und eine Tasse Tee genießen, wenn man diese Erinnerung an Flammen und Asche um sich hat.\n\nBitte, <Schlundgänger/Schlundgängerin>, tut mir einen Gefallen... beseitigt ihn, damit wir uns alle eine Tasse meiner Lieblingsmischung gönnen können!", sourceObjective = "Tötet Infernus den Unendlichen für Theotar.", completion = "Die süße Erlösung von der grausigen Grelle der Kreatur.", sourceObjectiveStatus = "unverified-source-field" }
quests[63855] = { id = 63855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erleichterter Übergang", description = "Korthia ist voller Gelegenheiten. Schaut Euch doch nur all diese interessanten Objekte an.\n\nIn Erwartung derartiger Wunder bin ich natürlich gut vorbereitet hergekommen. Suchen wir uns einen geeigneten Ort, um eine dauerhaftere Verbindung zwischen hier und meiner Zuflucht aufzubauen.\n\nUnsere gemeinsame Arbeit ist noch nicht zu Ende.", sourceObjective = "Erschafft eine Verbindung zwischen Korthia und Ve'naris Zuflucht.", progress = "Ich hätte dann jetzt gern meine Tasche, wenn Ihr sie habt.", completion = "Eine lohnenswerte Reise, die so viele Möglichkeiten eröffnet hat.\n\n<Ve'nari wühlt in der schweren Tasche herum und kramt ein paar ungewöhnliche Objekte hervor.>", sourceObjectiveStatus = "unverified-source-field" }
quests[63856] = { id = 63856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zusammentreffen der Pakte", description = "Auch wenn der Kerkermeister den Schlund nicht verlassen kann, reicht seine Grausamkeit weit über die Grenzen seines Gefängnisses hinaus.\n\nGlücklicherweise erholt die Archon sich von dem Angriff. Ihre Wunde soll jedoch... verstörende Eigenschaften haben.\n\nDie Ewigen und ihre Verbündeten erwarten Euch und Hochlord Fordragon in der Kammer der Richterin. Ich werde den Weg für Euch öffnen.\n\nMit ihrer Stimme habe ich gesprochen.", sourceObjective = "Sprecht mit Tal-Inara und betretet die Kammer der Richterin.", completion = "<Bolvar betrachtet fasziniert den Anblick vor ihm.>", sourceObjectiveStatus = "unverified-source-field" }
quests[63857] = { id = 63857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmen der Ewigen", description = "<Bolvar blickt zu den großen Figuren vor ihm, zu den unzähligen Toren, die sich in den Äther erstrecken.>\n\nDiese Kammer ist... wahrlich wundersam.\n\nDoch dies ist keine Zeit für Ehrfurcht. Die Geehrte Stimme muss sofort das Treffen eröffnen.", sourceObjective = "Hört Euch den Plan an.", completion = "Die Winterkönigin muss das nächste Ziel des Kerkermeisters sein.\n\nWir müssen unser Bestes geben, um sie zu beschützen.\n\nUnd ich habe schon ein paar Ideen, wie wir das tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[63858] = { id = 63858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mut der Seele", description = "Diese konfliktreiche Zeit ist für uns alle eine Prüfung, <Schlundgänger/Schlundgängerin>. Es bedarf großer Tapferkeit und einer starken Seele, um unseren Feinden ohne Angst entgegenzutreten.\n\nBegebt Euch in ihr Gebiet und zeigt ihnen die Macht Eures Mutes.", sourceObjective = "Beseitigt 15 Streitkräfte des Kerkermeisters in Cocyrus und Zovaals Kessel.", completion = "Ihr zeigt wahrhaftigen Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[63859] = { id = 63859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Läuten des Erfolgs", description = "Unsere Provosten bereiten Verstärkungsglocken vor, um zusätzliche Kyrianer zur Unterstützung unseres Angriffs herbeizurufen. Allerdings haben die Schlundgebundenen die Provosten angegriffen, um ihre Pläne zu durchkreuzen.\n\nIhr müsst unsere Provosten verteidigen, während sie ihre Arbeit erledigen, und dann jede Glocke läuten, um Verstärkung zu rufen.", sourceObjective = "Verteidigt die westliche, die östliche und die südliche Verstärkungsglocke und läutet sie.", completion = "Das Geräusch der Glocken stärkt unsere Herzen und gibt uns die Kraft, diese Schlacht zu gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63860] = { id = 63860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talisman des ewigen Gelehrten", description = "<Der Talisman ist verbeult und dreckig. Wer auch immer ihn hier versteckt hat, ist nicht gerade sanft damit umgegangen.\n\nArchivar Roh-Suir hat im Reliquiar der Erinnerung einen Platz für diesen Talisman reserviert.>", sourceObjective = "Bringt den beschädigten Talisman zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Wo... Wo habt Ihr den gefunden?\n\n<Der Archivar betrachtet den Talisman näher, um ihn zu untersuchen.>\n\nÄonen sind vergangen, seit ich den erblickt habe. Ich dachte, er wäre für immer verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63861] = { id = 63861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beginn der Sammlung", description = "Setzen wir unsere Arbeit fort, indem wir den wichtigsten Gegenstand für jede Gelehrtenforschung beschaffen: den verlorenen Kodex.\n\nEs wird eine Weile dauern, doch während wir unsere Arbeit fortsetzen, werden die Seiten dieses Werkes weiter anwachsen und gedeihen, wie Korthia es schon seit Äonen getan hat.\n\nDoch wo finden wir den Kodex? Zuvor lag er tief in Korthia verborgen, in der Grotte des Nachsinnens im Süden.\n\nWir können nur hoffen, dass die Truppen des Kerkermeisters ihn noch nicht entdeckt haben.", sourceObjective = "Beschafft den Kodex der Erinnerungen für Archivar Roh-Suir im Reliquiar der Erinnerung.", progress = "Habt ihr den Kodex gefunden? Ich hoffe, wir sind nicht zu spät.", completion = "Ja, ja. Das ist er. Prachtvoll, nicht wahr?\n\n<Der klamme Kodex überrascht den Archivar. Er fährt mit seiner Hand sanft über den Einband und flüstert eine ruhige und rätselhafte Beschwörungsformel.>\n\nDas sollte ihn vorerst schützen, doch die Beschwörungsformel wird nicht ewig halten. Wir müssen uns an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63863] = { id = 63863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereintes Rudel", description = "Obwohl wir meist wetteifern und unsere Unterschiede haben, arbeiten Nemea und ich bei größeren Bedrohungen zusammen. Das Rudel und die Phalynx sind erbitterte Kämpfer auf dem Schlachtfeld.\n\nEs wäre uns beiden eine Ehre, Euch in der bevorstehenden Schlacht zu unterstützen.\n\nBitte erlaubt Andira oder Gatamatos, Euch dabei zu helfen, die Champions des Kerkermeisters zu besiegen, die unsere Streitkräfte bedrohen.", sourceObjective = "Besiegt Malfestus, Domonus und Furus.", progress = "Jetzt, da diese Champions besiegt wurden, können unsere Streitkräfte vorstoßen.", completion = "Ihr zeigt wahrhaftigen Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[63864] = { id = 63864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die grässliche Mischung", description = "Grabstaub und Tüpfelkraut sind eine grässliche Geschmackskombination und Tubbins hat eine sehr große Ladung Tee mit diesem Zutaten gemacht.\n\nEr war so schrecklich, dass ich die ganze Kanne ins Feuer geschüttet habe. Aber dabei habe ich gemerkt, dass dieser Tee ein sehr guter Feuerlöscher ist!\n\nTubbins wird die ganze Ladung für Euch mitschleppen. Setzt sie sinnvoll ein, indem Ihr sie auf die instabilen Glutfunken in Zovaals Kessel werft.", sourceObjective = "Löscht 30 instabile Glutfunken.", completion = "Bitte sagt mir nicht, dass Ihr von diesem schrecklichen Gebräu getrunken habt. Für all unsere Mühen hier verdienen wir nur die feinsten Mischungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63867] = { id = 63867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressionsmanagement", description = "Ich selbst bin keine Musikerin, obschon ich die Unterhaltungsangebote in Tazavesh immer sehr genossen habe.\n\nUm diesem Horn eine Stimme zu verleihen, benötigt Ihr ein paar starke Emotionen.\n\nIn einigen der im Fluss der Seelen gefangenen Verdammten brodelt eine ungezügelte Wut. Verwendet dieses Entziehungsgerät, um die Wut aus den wütenden Schemen in Euer Instrument zu ziehen.\n\nMit den Zornesschreien, die Ihr erntet, könnt Ihr den Schleier des Schlunds durchdringen und Eure Verbündeten erreichen.\n\nIch vermute aber, dass Ihr keine sonderlich liebliche Ode fabrizieren werdet.", sourceObjective = "Nutzt das Entziehungsgerät, um die Wut der wütenden Schemen im Fluss der Seelen in Euer Instrument zu leiten.", completion = "Der Klang des Instruments wird für die meisten Ohren nicht angenehm sein, sollte wohl aber den Zweck erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63892] = { id = 63892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenmarken des Wahrsagers", description = "<Im Innern des Beutels befindet sich eine einzelne Runenmarke. Sie dreht und wendet sich, als ob eine unsichtbare Hand sie führen würde.\n\nIn den Stein sind filigrane Runen geritzt, die vage an die Vrykulsprache erinnern. Auf der Rückseite der Marke ist ein Hinweis, dass sie Teil eines Sets ist.>", sourceObjective = "Sammelt 20 Runenmarken und bringt sie zu Archivar Roh-Suir im Reliquiar der Erinnerung.", progress = "Meine Güte, ist das ein Beutel voller Runenmarken? Wie viele davon habt Ihr?", completion = "Ihr habt einen kompletten Satz Runenmarken des Wahrsagers gesammelt!\n\nDies war eines der ersten Relikte, das ich als Gelehrtenakolyth untersucht habe. Wenn Ihr die Marken werft, können Euch ihre Verteilung und Ausrichtung jegliche Frage beantworten. Allerdings bedarf es Erfahrung und einer Menge Intuition, um die Bedeutung richtig zu interpretieren.\n\nIch hätte nie erwartet, je wieder einen vollständigen Satz zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63895] = { id = 63895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wundertüte", description = "Interessant... Auralsequenzierer und eine ätherische Verschleierung. Behaltet sie vorerst, {name}. Ich habe da so einen Verdacht, dass sie Euch noch nützen könnten.\n\nAch, und hier ist auch für mich etwas Besonderes. Wenn ich mich nicht irre, und das tue ich so gut wie nie, dann ist das ein Projektionsmechanismus. Sehr praktisch!\n\nUnd was ist das? Wohl irgendeine Art Transportgerät. Wir sollten es umgehend testen.\n\nUnd mit \"wir\" meine ich natürlich Euch.", sourceObjective = "Testet das Transportgerät aus Ve'naris Tasche.", completion = "Dieser Projektor ist offenbar sehr nützlich. Scheint für eine sichere Landung zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63896] = { id = 63896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränen der Verdammten", description = "Um das Instrument im Schlund zu verankern und den von Euch gewünschten Effekt nutzbar zu machen, muss es mit dem rohen, ungefilterten Leid der in diesem verfluchten Gefängnis eingesperrten Seelen durchtränkt werden.\n\nTrauer ist hier im Überfluss vorhanden und damit einfach zu beschaffen. Ihr müsst nur zum Gorgoa reisen. Die Verdammten vergießen reichlich Tränen, die als kristallisierter Kummer in den Fluss der Seelen fallen und von ihm mitgeschwemmt werden.\n\nSeid vorsichtig, dass ihre Traurigkeit Euch nicht überwältigt.", sourceObjective = "Sammelt 10 Tränen der Verdammten aus dem Gorgoa, Fluss der Seelen.", completion = "Das Ausmaß der Trauer, die Ihr gesammelt habt, wird das Instrument an den Schlund binden.", sourceObjectiveStatus = "unverified-source-field" }
quests[63899] = { id = 63899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buch der Bindung: Die wahnsinnige Hexe", description = "<Ihr hört eine dumpfe Stimme aus dem Buch, die immer wieder von einem Knacken und Rauschen unterbrochen wird. Die Worte der Stimme sind kaum vernehmbar, aber Ihr erkennt, dass sie unablässig darum bittet, irgendwelche blutroten Seiten zu sammeln.\n\nBeim Durchblättern des Buchs bemerkt Ihr, dass viele der Seiten fehlen.\n\nWenn jemand die Seiten finden würde, könnte das Buch zum Archivar zurückgebracht und repariert werden.>", sourceObjective = "Sammelt 12 blutrote Seiten und bringt sie zu Archivar Roh-Suir im Reliquiar der Erinnerung.", progress = "Spricht dieses Buch etwa...?", completion = "Gelehrte im Quorum des Suchers haben sich eingehend mit diesem Folianten befasst.\n\nEs scheint allerdings, als hätten weder ein Schlundgebundener noch ein Wildtier dieses Buch zerstört, sondern ein anderer Gelehrter. Das ist besorgniserregend.\n\nZu unserer Sicherheit werde ich alle fehlenden Seiten bis auf eine erneut in das Buch einbinden, bevor wir es im Archiv lagern. Wir sollten dieses Relikt erst vollständig restaurieren, wenn wir mehr darüber wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63901] = { id = 63901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fokussieren des Auges", description = "Die Kombination aus Trauer und Wut, die Ihr zusammengetragen habt, reicht für Eure Zwecke aus. Vermutlich.\n\nWenn Ihr darauf besteht, dieses unvernünftige Unterfangen zum Abschluss zu bringen, benutzt das Horn an der Terminusplattform, wo der Fluss der Seelen nach oben gen Torghast fließt. Die Energien dort sind wahrhaftig sehr stark.\n\nDie Anwesenheit Eurer goldenen Verbündeten sollte das Auge des Kerkermeisters auf Euch lenken. Ich hoffe nur, dass dies nicht Euer Ende sein wird. Ich hasse es, eine Investition verschwendet zu sehen.", sourceObjective = "Geht zur Terminusplattform und benutzt das Ilskahorn, um Odyns Zorn zu beschwören.", completion = "Unsere heutige Leistung wird man noch in Liedern verewigen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63902] = { id = 63902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gute Nachricht, Freunde!", description = "Kommt, <mein Freund/meine Liebe>. Verlassen wir diesen schrecklichen Ort.\n\nEure Kameraden brennen bestimmt schon darauf, von der Niederlage des Auges zu erfahren. Ich werde Euch zu ihnen bringen.\n\nGebt mir Bescheid, wenn Ihr bereit zum Aufbruch seid, {name}.", sourceObjective = "Fliegt mit Danica nach Korthia, um Bolvar die Neuigkeiten zu überbringen.", completion = "Das Auge ist besiegt? Das sind in der Tat gute Nachrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63903] = { id = 63903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf das Sanktum", description = "Der Kerkermeister hat die Siegel aller vier Pakte an sich gebracht. Er hat eindeutig vor, aus dem Schlund zu entkommen und das Siegel der Richterin in Oribos zu stehlen.\n\nDas dürfen wir nicht zulassen.\n\nAn der Spitze von Torghast liegt das Sanktum der Herrschaft, der Machtsitz des Kerkermeisters. Die Zeit ist gekommen, dieses dunkle Reich zu betreten.\n\nMit Sicherheit wird Sylvanas Windläufer die Streitkräfte befehligen, die versuchen werden, uns aufzuhalten. Wir müssen sie besiegen... und Anduin Wrynn aus ihrem Griff befreien.\n\nSammelt Eure Truppen, {name}. Die Schwarze Klinge wird Euch zur Seite stehen.", sourceObjective = "Besiegt Sylvanas Windläufer im Sanktum der Herrschaft.", completion = "Der Kerkermeister hat, was er wollte... zusammen mit Anduin an seiner Seite.\n\nUnser einziger Sieg, wenn man es denn so bezeichnen will, ist, dass wir Sylvanas in Gewahrsam haben.\n\nIch bete, dass sie über nützliches Wissen verfügt, damit wir dem nächsten Schritt des Kerkermeisters zuvorkommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[63904] = { id = 63904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Ardenwalds", description = "Ich habe mein Siegel im Herz des Waldes verborgen, um es vor den Streitkräften des Schlundes zu bewahren.\n\nDoch das Horn hat nach Hilfe gerufen.\n\nGeht mit Euren Verbündeten und ergründet den Grund des Rufes.", sourceObjective = "Untersucht das Herz des Waldes.", progress = "Ist mein Siegel in Sicherheit?", completion = "All unsere Bemühungen waren vergebens.\n\nUnser Feind kommt der Verwirklichung seines Plans immer näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[63908] = { id = 63908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bollwerk der göttlichen Absicht", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diesen Schild im Reliquiar der Erinnerung.>", sourceObjective = "Bringt das Bollwerk der göttlichen Absicht zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Dieser Schild stammt aus dem Jenseits, das wir informell als Gasthaus der Ewigkeit bezeichnen.\n\nWenn ein Geist das Gasthaus erreicht, legt er seine Waffen ab. Dieser Schild wurde zurückgelassen, als sein Besitzer sich zu den Ewigen Kaminfeuerfestivitäten gesellte. Es wäre nicht ganz richtig zu sagen, dass der Schild mit dem Gespür für Pflicht und Selbstlosigkeit seines ehemaligen Besitzers erfüllt ist... er ist geradezu eine Verkörperung dieser Konzepte.\n\nEs würde mich sehr interessieren, ob man diesen Schild im Kampf einsetzen kann. Die Ergebnisse eines solchen Versuchs wären äußerst faszinierend. Eines Tages vielleicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[63909] = { id = 63909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarnung des Wechselbalgs", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diese Maske im Reliquiar der Erinnerung.>", sourceObjective = "Bringt die Tarnung des Wechselbalgs zu Archivar Roh-Suir im Reliquiar der Erinnerung.", completion = "Was für ein Fund!\n\nDie Tarnung des Wechselbalgs verfügt über die Fähigkeit, das Aussehen ihres Trägers überzeugend zu verändern, aber sie hat auch ihren eigenen Kopf. Der Träger kann die Illusion nicht kontrollieren, und die Maske kann ihn oder sie in peinliche oder gefährliche Situationen bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63910] = { id = 63910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Netherstern", description = "<Ihr kennt das Relikt aus dem Archivarskodex.\n\nDie Energiequelle ist fast erschöpft, könnte aber durch den Kontakt mit roher, ungefilterter Anima wieder aufgeladen werden. Die nahe gelegenen Risse sollten sich dafür eignen.>", sourceObjective = "Ladet den Netherstern wieder auf und bringt ihn zu Archivar Roh-Suir im Reliquiar der Erinnerung.", completion = "Wenn wir Gelehrten empfehlen, wichtige Relikte in Sicherheit zu verwahren, dann ist der Netherstern genau die Art von Relikt, die wir im Sinn haben. Könnt Ihr Euch vorstellen, wie viel Schaden er in den Händen eines... Opportunisten anrichten könnte?", sourceObjectiveStatus = "unverified-source-field" }
quests[63911] = { id = 63911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Singstahlbarren", description = "<Der Barren jault ein trällerndes Vibrato.>\n\nOh weh! Diese Grobiane hämmern gnadenlos auf mich ein und formen meinen Körper, damit er ihren bösen Absichten dienen kann.\n\nSchande! Schande über sie.\n\n<Der Barren stößt einen schrillen Kampfschrei aus.>\n\nLasst die Schlundgebundenen den Hammer spüren!", sourceObjective = "Besiegt die Eindringlinge der Schlundgebundenen und bringt dann den Singstahlbarren zu Archivar Roh-Suir im Reliquiar der Erinnerung.", completion = "In all meinen Jahren als Forscher hätte ich so etwas nie erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[63912] = { id = 63912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelskarte der Schattenlande", description = "<Ihr kennt das Relikt aus dem Archivarskodex.\n\nDie Schlundgebundenen haben die Karte weggeworfen, vermutlich weil sie sie für nutzlos erachtet haben.\n\nUnd ohne die zugehörigen Kartendaten zur Bestimmung der relativen Standorte von jenseitigen Leben in den Schattenlanden ist die Karte in der Tat nutzlos. Wenn man die Forschungsergebnisse von verstorbenen Gelehrten erhalten könnte, wäre es möglich, die Karte dem Archivar voll funktionsfähig zurückzubringen.>", sourceObjective = "Sammelt 6 Schriftrollen zur Erforschung der Jenseitsnavigation und bringt sie zu Archivar Roh-Suir im Reliquiar der Erinnerung.", progress = "Ist das die fehlende Karte?", completion = "Aha! Ihr habt die Himmelskarte der Schattenlande gefunden.\n\nDie Karte kann zusammen mit den Kartendaten, die Ihr gesammelt habt, wieder funktionsfähig gemacht werden. Es wird einige Zeit dauern, die Ergebnisse zu analysieren und zu interpretieren. Aber jetzt, da das sich Relikt wieder im Archiv befindet, kann ich ja damit beginnen.\n\nMal sehen, wo ich sie aufhänge...", sourceObjectiveStatus = "unverified-source-field" }
quests[63913] = { id = 63913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instabile Sprengstoffkugel", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für dieses Gerät im Reliquiar der Erinnerung.>", sourceObjective = "Bringt die instabile Sprengstoffkugel zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Ich weiß zu würdigen, wie sorgfältig Ihr mit diesem Relikt umgegangen seid. Es grenzt an ein Wunder, dass es nicht explodiert ist, als Korthia angegriffen wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[63914] = { id = 63914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chiffre der Erkenntnis", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für die Chiffre im Reliquiar der Erinnerung.>", sourceObjective = "Bringt die Chiffre der Erkenntnis zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Bei den Sternen! Nur eine dieser Sprachen zu verstehen, würde es ermöglichen, alle von ihnen zu übersetzen. Wir müssen dies weiter untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63915] = { id = 63915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trommel des Todesloas", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diese Trommel im Reliquiar der Erinnerung.>", sourceObjective = "Bringt die Trommel des Todesloas zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Ich konnte hören, dass Ihr Euch mit der Trommel nähert, bevor ich Euch sehen konnte. Und seltsamerweise dachte ich, dass noch jemand bei Euch ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63916] = { id = 63916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sack voller fremdartiger Erde", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diese Erde im Reliquiar der Erinnerung.>", sourceObjective = "Bringt den Sack voller fremdartiger Erde zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Diese Erde lässt jede Art von Pflanze wachsen, und zwar überall.\n\nDas ist nicht das gefährlichste Relikt, das im Archiv fehlt, und doch könnte es das nützlichste sein. Mit genügend Zeit und Geduld könnte man damit die üppige Schönheit von Korthia wiederherstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63917] = { id = 63917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiglebende Statuette", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diese Statuette im Reliquiar der Erinnerung.>", sourceObjective = "Bringt die ewiglebende Statuette zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Ich hoffe, Ihr habt nichts von dem geglaubt, was dieses kleine Monster Euch erzählt hat.\n\nEs ist absolut unfähig, die Wahrheit zu sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63918] = { id = 63918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obelisk düsterer Kunde", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diesen Obelisken im Reliquiar der Erinnerung.>", sourceObjective = "Bringt den Obelisken düsterer Kunde zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Wir müssen in der Umgebung dieses Obelisken vorsichtig sein.\n\nSchon mehr als ein Bediensteter wurde bei der Erforschung des Relikts in den Wahnsinn getrieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63919] = { id = 63919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buch der Bindung: Der gepeinigte Zauberer", description = "<Ihr hört eine dumpfe Stimme aus dem Buch, die immer wieder von einem Knacken und Rauschen unterbrochen wird. Die Worte der Stimme sind kaum vernehmbar, aber Ihr erkennt, dass sie unablässig darum bittet, irgendwelche azurblauen Seiten zu sammeln.\n\nBeim Durchblättern des Buchs bemerkt Ihr, dass viele der Seiten fehlen.\n\nWenn jemand die Seiten finden würde, könnte das Buch zum Archivar zurückgebracht und repariert werden.>", sourceObjective = "Sammelt 10 azurblaue Seiten und bringt sie zu Archivar Roh-Suir im Reliquiar der Erinnerung.", progress = "Diese komischen sprechenden Bücher bereiten mir... Unbehagen.", completion = "Das hier scheint so etwas wie ein Zwilling des blutroten Buches zu sein, mit dem sich die Gelehrten im Quorum des Suchers befasst haben.\n\nDa jemand den Einband des Buches mit voller Absicht von seinen Seiten getrennt hat, werde ich alle azurblauen Seiten bis auf eine wieder einbinden, bevor ich es im Archiv lagere.", sourceObjectiveStatus = "unverified-source-field" }
quests[63920] = { id = 63920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvolles Entschlüsselungsgerät", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für dieses Gerät im Reliquiar der Erinnerung.>", sourceObjective = "Bringt das geheimnisvolle Entschlüsselungsgerät zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Obwohl ich die Funktionsweise dieses Relikts nur annäherungsweise verstehe, kann es die Komplexität von Kommunikation in eine Form bringen, die frei von Subtilität, Arglist oder Gleichnissen ist. Pure Logik.", sourceObjectiveStatus = "unverified-source-field" }
quests[63921] = { id = 63921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring der Selbstreflexion", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diesen Ring im Reliquiar der Erinnerung.>", sourceObjective = "Bringt den Ring der Selbstreflexion zu Archivar Roh-Suir im Reliquiar der Erinnerung.", completion = "Ich bin schon gespannt darauf, zu erfahren, wie dieser seltsame Ring funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[63922] = { id = 63922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschnittkurzschwert", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für dieses Kurzschwert im Reliquiar der Erinnerung.>", sourceObjective = "Bringt das Schattenschnittkurzschwert zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Die schattenspaltenden Eigenschaften der Klinge mögen zwar wie ein Taschenspielertrick erscheinen, aber ich glaube dennoch, dass dies eines der gefährlichsten Relikte in unserer Obhut ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63923] = { id = 63923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holzschnitzerei der Familie Lang", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diese Holzschnitzerei im Reliquiar der Erinnerung.>", sourceObjective = "Bringt die Holzschnitzerei der Familie Lang zu Archivar Roh-Suir im Reliquiar der Erinnerung.\n\nBereitgestellter Gegenstand:", completion = "Ich glaube, dieses Relikt kann uns sowohl etwas über die Geschichte als auch über die Zukunft lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63924] = { id = 63924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorakklauenfetisch", description = "<Dank Eurer Vertrautheit mit dem Archivarskodex wisst Ihr, dass es sich um eines der verschollenen Relikte handelt.\n\nArchivar Roh-Suir hat einen Platz für diesen Fetisch im Reliquiar der Erinnerung.>", sourceObjective = "Bringt den Gorakklauenfetisch zu Archivar Roh-Suir im Reliquiar der Erinnerung.", completion = "Ein Teil von Gorak Tul lebt in diesem Fetisch weiter. Seine Verderbnis ist immer noch sehr präsent.", sourceObjectiveStatus = "unverified-source-field" }
quests[63934] = { id = 63934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postraub", description = "Seid gegrüßt, <Sterblicher/Sterbliche>!\n\nIch bin auf einer Mission, Nachrichten an unsere Verbündeten hier im aufregenden Korthia zu überbringen. Allerdings war ich nicht in der Lage, meine Aufgabe zu erfüllen.\n\nDie Botschaften, für deren Transport ich programmiert wurde, wurden von Schlundgebundenen gestohlen und dann überall inkorrekt auf dem Boden abgelegt.\n\nKönntet Ihr diese Nachrichten einsammeln und zu mir bringen? Ich sorge dann dafür, dass sie den vorgesehenen Empfängern zugestellt werden.\n\nIch danke Euch!", sourceObjective = "Beschafft 6 gestohlene Nachrichten aus der Höhle des Gelehrten.", progress = "Die Aufgabe muss erfüllt werden.", completion = "Dies sind die Nachrichten, die gestohlen wurden! Ich belobige Euch für ihre Wiederbeschaffung.\n\nOh, da scheint mindestens eine zusätzliche dabei zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[63935] = { id = 63935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geliebte Wurzeln", description = "Korthia. Ein gepeinigter Schwesterwald.\n\nDoch inmitten der Zerstörung gedeiht noch Hoffnung.\n\nSammelt die Anima und beginnt mit dem Wiederaufbau.", sourceObjective = "Sammelt 8 Restanima am Archiv in Korthia.", progress = "Sät Wachstum.", completion = "Wertvolle Anima, die geteilt wird. Ein ehrenwertes Opfer.", sourceObjectiveStatus = "unverified-source-field" }
quests[63936] = { id = 63936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlungene Anima", description = "Sika hat Idee!\n\nVerschlinger... verschlingen. Fressen alles! Auch Anima.\n\nWenn wir Verschlingern Anima abnehmen, gehört sie uns!", sourceObjective = "Gewinnt 12 verschlungene Anima von den Verschlingern im Ästuarium des Erwachens zurück.", progress = "Sika fragt sich, wie Anima wohl schmeckt.", completion = "Danke! Wow... Kann kaum glauben, dass das in Verschlinger war!\n\nSika bringt Anima zu denen, die sie am meisten brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63937] = { id = 63937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiese, große, spitze Zähne", description = "Hier gibt es jede Menge interessante Dinge zu erlegen! Bären, Vögel, Schlundgebundene und Gromits!\n\nFangen wir doch mit den Gromits an. Zieht los und erlegt die grimmigen Gromits am Zerfleischerausguck und bringt mir ihre FANGZÄHNE! Zähne kann ich immer gebrauchen.", sourceObjective = "Sammelt 6 Zähne von grimmigen Gromits.", progress = "Ich mag lange Zähne. Richtig spitze Fangzähne. Aber die kurzen sind auch schön.", completion = "JAAAAA! Die sind gut! Schaut nur, wie lang und spitz die sind! Ich werde sie gleich verarbeiten! Danke schön!", sourceObjectiveStatus = "unverified-source-field" }
quests[63944] = { id = 63944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korthia erwartet Euch", description = "Macht Euch bereit, {name}.Unsere Verbündeten erwarten Euch in Korthia.", sourceObjective = "Meldet Euch bei Tal-Galan in der Zuflucht des Hüters in Korthia.", completion = "Ah, ja. Eure Anima scheint vertraut.\n\nWir haben uns schon gefragt, wann Ihr kommen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[63945] = { id = 63945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seelenklinge", description = "Die Runenklinge eines Nekrolords kann in diesem Reich eine mächtige Waffe sein. Unzählige Seelen sind bereit, ihre Anima zu opfern, um ihr eigenes Leiden zu beenden und dem Kerkermeister eine Niederlage beizubringen.\n\nNehmt eine meiner Runenklingen und ladet sie mit der Macht bereitwilliger Seelen auf, die Ihr hier vorfindet.\n\nWenn die Klinge aufgeladen ist, könnt Ihr sie verwenden, um ihre Truppen hier zu vernichten.", sourceObjective = "Ladet Heirmirs Runenklinge mit bereitwilligen Seelen auf und tötet damit das Auge des Gorgoa.", progress = "Hat meine Klinge den Geschmack des Sieges gekostet?", completion = "<Knochenschmiedin Heirmir nimmt die Runenklinge von Euch entgegen und mustert sie aufmerksam.>\n\nNicht schlecht, {name}. Es gibt immer etwas zu verbessern... aber gar nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63949] = { id = 63949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal gestalten", description = "Macht und Bösartigkeit des Kerkermeisters nehmen immer weiter zu. Für unsere Widerstandskraft muss das gleiche gelten.\n\nSammelt Eure Verbündeten, {name}. Treibt die Finsternis, die uns alle zu verschlingen droht, zurück.\n\nZusammen werden wir obsiegen.\n\nMöge die Vorsehung Eure Hand führen.", sourceObjective = "Vereitelt die Pläne des Kerkermeisters in Korthia und im Schlund, indem Ihr Paktangriffe und tägliche Quests abschließt, Schätze plündert sowie seltene Kreaturen und die Peiniger von Torghast besiegt.", completion = "Die Fäden des Schicksals durchdringen Euch, Schlundgänger.\n\nGenau, wie es die Prophezeiung vorhergesagt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[63950] = { id = 63950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenschwingenkrallen", description = "Meine Jäger sind noch nicht sonderlich mit diesem Land vertraut, aber wir haben furchterregende Bestien entdeckt, die es bewohnen.\n\nDazu zählen auch die Klingenschwingen, bösartige Raubtiere mit schrecklichen Krallen... und der Reizbarkeit der Vorkai.\n\n<Herne grinst grimmig.>\n\nBringt mir ein paar ihrer Krallen, um unseren Nachwuchsjägern zu zeigen, mit welchen Bestien sie es zu tun bekommen werden.", sourceObjective = "Sammelt 10 Klingenschwingenkrallen.", progress = "Habt Ihr diese Klingenschwingenkrallen?", completion = "Diese Krallen sind wirklich ausgezeichnet. Und sie sehen aus, als könnten sie einem ein Auge herausreißen! <Herne kichert ironisch.>\n\nSie werden bestimmt eine Menge Aufmerksamkeit von den Rekruten der Wilden Jagd bekommen.\n\nHabt Dank, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[63951] = { id = 63951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schattenhafter Ort", completion = "Ausgezeichnete Arbeit, Schlundgänger." }
quests[63952] = { id = 63952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handarbeit", description = "Wir brauchen mehr Konstrukte an den Frontlinien, aber wir haben keine Körper, Köpfe oder Beine!\n\nRathan fertigt die bestmöglichen Konstrukte aus dem, WAS wir haben... einer Menge Hände.\n\nKeine Fragen dazu!\n\nEs gibt Feinde in Calcis, die wir ausschalten müssen. Nehmt die Hände und tötet diese Dinger!", sourceObjective = "Tötet 8 schlundgebundene Seelenbrecher, 4 kristalline Wächter, Lady Nalis und den Glasmacher.", completion = "<Markgräfin Sin'dane wirkt beeindruckt... oder verärgert... oder angewidert... oder besorgt?>\n\nHm. Mit genügend Händen ist wohl DOCH alles möglich...", sourceObjectiveStatus = "unverified-source-field" }
quests[63953] = { id = 63953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korraks Rache" }
quests[63954] = { id = 63954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelte Geheimnisse", description = "Ah, Korthia. Was für Geheimnisse werden wir offenlegen?\n\nMeine Partner haben hart daran gearbeitet, in diesem verheerten Land verschiedene kleinere Gegenstände von Interesse aufzuspüren und sicherzustellen. Nichts von großer Bedeutung, kann ich Euch versichern.\n\nSie haben diese Gegenstände in dafür vorgesehenen Behältern gesichert, die nun im Quorum des Suchers zur Abholung bereitstehen. Aber keine Sorge, sie sind mit einem undurchdringlichen Siegel verschlossen, um sowohl den Inhalt als auch den Zusteller zu schützen.\n\nWenn Ihr mir diese versiegelten Behälter bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Beschafft 5 versiegelte Behälter aus dem Quorum des Suchers.", progress = "Habt Ihr die versiegelten Behälter?", completion = "Wunderbar! Ihr habt alles mitgebracht, um das ich gebeten habe.\n\nMacht Euch wie gesagt keine Sorgen um den Inhalt dieser Behälter. Er stellt keine Gefahr für Euch dar.\n\nHier ist Eure versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63955] = { id = 63955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelte Geheimnisse", description = "Ah, Korthia. Was für Geheimnisse werden wir offenlegen?\n\nMeine Partner haben hart daran gearbeitet, in diesem verheerten Land verschiedene kleinere Gegenstände von Interesse aufzuspüren und sicherzustellen. Nichts von großer Bedeutung, kann ich Euch versichern.\n\nSie haben diese Gegenstände in dafür vorgesehenen Behältern gesichert, die nun vor dem Archiv zur Abholung bereitstehen. Aber keine Sorge, sie sind mit einem undurchdringlichen Siegel verschlossen, um sowohl den Inhalt als auch den Zusteller zu schützen.\n\nWenn Ihr mir diese versiegelten Behälter bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Beschafft 5 versiegelte Behälter aus dem Archiv in Korthia.", progress = "Habt Ihr die versiegelten Behälter?", completion = "Wunderbar! Ihr habt alles mitgebracht, um das ich gebeten habe.\n\nMacht Euch wie gesagt keine Sorgen um den Inhalt dieser Behälter. Er stellt keine Gefahr für Euch dar.\n\nHier ist Eure versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63956] = { id = 63956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelte Geheimnisse", description = "Ah, Korthia. Was für Geheimnisse werden wir offenlegen?\n\nMeine Partner haben hart daran gearbeitet, in diesem verheerten Land verschiedene kleinere Gegenstände von Interesse aufzuspüren und sicherzustellen. Nichts von großer Bedeutung, kann ich Euch versichern.\n\nSie haben diese Gegenstände in dafür vorgesehenen Behältern gesichert, die nun am Windgepeitschten Nistgipfel zur Abholung bereitstehen. Aber keine Sorge, sie sind mit einem undurchdringlichen Siegel verschlossen, um sowohl den Inhalt als auch den Zusteller zu schützen.\n\nWenn Ihr mir diese versiegelten Behälter bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Beschafft 5 versiegelte Behälter vom Windgepeitschten Nistgipfel in Korthia.", progress = "Habt Ihr die versiegelten Behälter?", completion = "Wunderbar! Ihr habt alles mitgebracht, um das ich gebeten habe.\n\nMacht Euch wie gesagt keine Sorgen um den Inhalt dieser Behälter. Er stellt keine Gefahr für Euch dar.\n\nHier ist Eure versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63957] = { id = 63957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtungsdaten", description = "Ich grüße Euch, <Schlundgänger/Schlundgängerin>. Habt Ihr einen Moment Zeit?\n\nWie Ihr sicher wisst, hat mein Kartell insgeheim Beobachtungsgeräte über ganz Korthia verteilt. Aber diese Daten nützen uns nichts, wenn sie nicht abgerufen werden. Und genau da kommt Ihr ins Spiel.\n\nDie Aufzeichnungen im Quorum des Suchers sollten zur Abholung bereit sein. Die Geräte selbst werdet Ihr nicht sehen können, aber die Daten erscheinen Euch als hell leuchtende Kugel.\n\nWenn Ihr mir diese Daten bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Sammelt 5 Beobachtungsdaten im Quorum des Suchers in Korthia.", progress = "Habt Ihr die Beobachtungsdaten aus dem Quorum des Suchers beschafft?", completion = "Der Name \"Quorum des Suchers\" ist mir ein Rätsel, seit ich ihn das erste Mal gehört habe. Was sucht dieser Sucher? Und was macht ein Quorum aus? Was ist dort vor sich gegangen?\n\nDiese Fragen bleiben vielleicht für immer unbeantwortet, vielleicht aber auch nicht. Hier ist Eure Belohnung, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63958] = { id = 63958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtungsdaten", sourceObjective = "Sammelt 5 Beobachtungsdaten vor dem Archiv in Korthia ein.", progress = "Habt Ihr die Beobachtungsdaten aus dem Archiv beschafft?", completion = "Das Archiv ist der Grund dafür, dass der Kerkermeister seine Ketten gegen Korthia gerichtet hat, denn es enthält viele Geheimnisse der Schattenlande.\n\nKönnten wir nur einen kleinen Blick erhaschen, wie es funktioniert und was es alles enthält, wären diese Informationen wirklich ausgesprochen wertvoll.\n\nHier ist Eure Belohnung, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63959] = { id = 63959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtungsdaten", description = "Ich grüße Euch, <Schlundgänger/Schlundgängerin>. Habt Ihr einen Moment Zeit?\n\nWie Ihr sicher wisst, hat mein Kartell insgeheim Beobachtungsgeräte über ganz Korthia verteilt. Aber diese Daten nützen uns nichts, wenn sie nicht abgerufen werden. Und genau da kommt Ihr ins Spiel.\n\nDie Aufzeichnungen im Refugium der Weisung sollten zur Abholung bereit sein. Die Geräte selbst werdet Ihr nicht sehen können, aber die Daten erscheinen Euch als hell leuchtende Kugel.\n\nWenn Ihr mir diese Daten bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Beschafft 5 Beobachtungsdaten aus dem Refugium der Weisung in Korthia.", progress = "Habt Ihr die Beobachtungsdaten aus dem Refugium der Weisung beschafft?", completion = "Die Verschlinger haben im Refugium der Weisung viel zerstört, was uns vielleicht noch sehr geholfen hätte. Aber diese Informationen sind trotzdem wertvoll.\n\nHier ist Eure Belohnung, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63960] = { id = 63960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtungsdaten", description = "Ich grüße Euch, <Schlundgänger/Schlundgängerin>. Habt Ihr einen Moment Zeit?\n\nWie Ihr sicher wisst, hat mein Kartell insgeheim Beobachtungsgeräte über ganz Korthia verteilt. Aber diese Daten nützen uns nichts, wenn sie nicht abgerufen werden. Und genau da kommt Ihr ins Spiel.\n\nDie Aufzeichnungen am Windgepeitschten Nistgipfel und am Ästuarium des Erwachens sollten zur Abholung bereit sein. Die Geräte selbst werdet Ihr nicht sehen können, aber die Daten erscheinen Euch als hell leuchtende Kugel.\n\nUnd vergesst nicht, auch unter der Erde nachzusehen!\n\nWenn Ihr mir diese Daten bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Sammelt 5 Beobachtungsdaten am Windgepeitschten Nistgipfel und am Ästuarium des Erwachens in Korthia ein.", progress = "Habt Ihr die Beobachtungsdaten vom Windgepeitschten Nistgipfel und dem Ästuarium des Erwachens beschafft?", completion = "Orte wie der Nistgipfel und das Ästuarium waren gewiss schon vor all dieser Zerstörung ausgesprochen trostlos. Was für interessante Kreaturen sich dort versammeln.\n\nOb sie wohl alle diese Veränderungen überleben? Oder werden sich einige anpassen und sogar noch gefährlicher werden?\n\nHier ist Eure Belohnung, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63961] = { id = 63961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelte Geheimnisse", description = "Ah, Korthia. Was für Geheimnisse werden wir offenlegen?\n\nMeine Partner haben hart daran gearbeitet, in diesem verheerten Land verschiedene kleinere Gegenstände von Interesse aufzuspüren und sicherzustellen. Nichts von großer Bedeutung, kann ich Euch versichern.\n\nSie haben diese Gegenstände in dafür vorgesehenen Behältern gesichert, die nun am Zerfleischerausguck zur Abholung bereitstehen. Aber keine Sorge, sie sind mit einem undurchdringlichen Siegel verschlossen, um sowohl den Inhalt als auch den Zusteller zu schützen.\n\nWenn Ihr mir diese versiegelten Behälter bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Beschafft 5 versiegelte Behälter vom Zerfleischerausguck in Korthia.", progress = "Habt Ihr die versiegelten Behälter?", completion = "Wunderbar! Ihr habt alles mitgebracht, um das ich gebeten habe.\n\nMacht Euch wie gesagt keine Sorgen um den Inhalt dieser Behälter. Er stellt keine Gefahr für Euch dar.\n\nHier ist Eure versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63962] = { id = 63962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtungsdaten", description = "Ich grüße Euch, <Schlundgänger/Schlundgängerin>. Habt Ihr einen Moment Zeit?\n\nWie Ihr sicher wisst, hat mein Kartell insgeheim Beobachtungsgeräte über ganz Korthia verteilt. Aber diese Daten nützen uns nichts, wenn sie nicht abgerufen werden. Und genau da kommt Ihr ins Spiel.\n\nDie Aufzeichnungen am Zerfleischerausguck sollten zur Abholung bereit sein. Die Geräte selbst werdet Ihr nicht sehen können, aber die Daten erscheinen Euch als hell leuchtende Kugel.\n\nWenn Ihr mir diese Daten bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Sammelt 5 Beobachtungsdaten am Zerfleischerausguck in Korthia.", progress = "Habt Ihr die Beobachtungsdaten vom Zerfleischerausguck beschafft?", completion = "Ausgezeichnet, diese Daten werden uns gute Dienste leisten. Endlich können wir einige unserer Fragen zu Korthia und dem Zerfleischerausguck beantworten. Haben dort schon immer solch furchtbare Kreaturen gehaust, oder steckt noch mehr dahinter?\n\nHier ist Eure Belohnung, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63963] = { id = 63963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlerkopfgeld: Reißmalm", description = "Neue Länder bieten neue Möglichkeiten. Wer uns ein Stück des schweren Stachelbalgs von der als Reißmalm bekannten Bestie bringt, erhält von uns im Gegenzug eine Anzahl wertvoller Gegenstände.\n\nZaghafte Sammler brauchen sich nicht zu bewerben.\n\nBringt bitte diese Probe zu Ta'nasi in der Zuflucht des Hüters.", sourceObjective = "Besorgt einen schweren Stachelbalg von Reißmalm.", progress = "Habt Ihr etwas zum Tauschen?", completion = "<Ta'nasi zieht an dem Balg, um seine Festigkeit zu prüfen.>\n\nEine ausgezeichnete Probe. Das reicht vollkommen.\n\nUnd, wie versprochen, hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63964] = { id = 63964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittlerkopfgeld: Grimmklaue", description = "Neue Länder bieten neue Möglichkeiten. Wer uns den intakten verknöcherten Schnabel der als Grimmklaue bekannten Bestie bringt, erhält von uns im Gegenzug eine Anzahl wertvoller Gegenstände.\n\nZaghafte Sammler brauchen sich nicht zu bewerben.\n\nBringt bitte diese Probe zu Ta'nasi in der Zuflucht des Hüters.", sourceObjective = "Besorgt einen verknöcherten ausgewachsenen Schnabel von Grimmklaue.", progress = "Habt Ihr etwas zum Tauschen?", completion = "<Ta'nasi klopft mit dem stabilen Schnabel auf ihre Handfläche und lauscht konzentriert.>\n\nEine ausgezeichnete Probe. Das reicht vollkommen.\n\nUnd, wie versprochen, hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63965] = { id = 63965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Klingenschwingeneier", description = "Die Natur hier in Korthia ist wirklich erstaunlich! So viele interessante Lebewesen...\n\nSagt mal, kennt Ihr diese Flugtiere mit den Krallen, die Klingenschwingen? Die stoßen manchmal ihre Eier aus dem Nest und dann ignorieren sie sie einfach! Wenn Ihr verlassene Eier findet, könntet Ihr sie wohl zu mir bringen?\n\nAber ganz vorsichtig, bitte! Ich frage mich, ob man sie zähmen kann...\n\nWenn nicht, nun... dann wäre es auch nicht das erste Mal, dass meine Fühler angeknabbert werden.", sourceObjective = "Sammelt 5 Klingenschwingeneier.", completion = "Schaut Euch nur diese wunderbaren Eier an! Ich kann sogar ihren Herzschlag hören.\n\nDies ist der Beginn von etwas ganz Besonderem, ich weiß es einfach.", sourceObjectiveStatus = "unverified-source-field" }
quests[63968] = { id = 63968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Tiegel säubern", description = "Die Winterkönigin hat eine Jagd einberufen. Wir werden sicherstellen, dass der Tiegel der Verdammten noch heute von den Truppen des Kerkermeisters befreit wird.\n\nTragt Euren Teil dazu bei und macht Jagd auf alle Feinde, die Ihr findet.", sourceObjective = "Tötet 30 Feinde im Tiegel der Verdammten und in Calcis.", completion = "Die Jagd ist noch nicht vorbei, doch Ihr habt Euren Platz in den Annalen ihres Sieges bereits verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[63969] = { id = 63969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dräuende Dunkelheit", description = "Die Winterkönigin hat an diesem Ort eine Jagd einberufen, weil es Berichte über eine gewaltige, unnatürliche Finsternis gibt, die sich in den oberen Regionen ausbreitet.\n\nDie Wilde Jagd ist tapfer, aber nicht töricht. Wir müssen mehr über diese Finsternis erfahren, bevor wir uns in sie hineinstürzen.\n\nDurchsucht die Leichen unserer Feinde in der Nähe nach Hinweisen.", sourceObjective = "Sammelt 1 |4Ritualbuch der Schlundgebundenen:Ritualbücher der Schlundgebundenen;, 10 Schnipsel eines Briefs der Schlundgebundenen und 15 dunkles Mark.", progress = "Habt Ihr schon etwas über die Finsternis herausgefunden?", completion = "Wir werden die Ursache dieser Finsternis finden und auslöschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63970] = { id = 63970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Seele wird zurückgelassen", description = "Hört Ihr die Schreie der gequälten Seelen, die im Gorgoa gefangen sind?\n\nHier fließt der schaurige Fluss der Seelen, angeschwollen von Grausamkeiten und den Qualen unschuldiger Opfer.\n\nUnser tapferes Regiment von Druidengeistern hat den Angriff in den Fluss angeführt, um diese verlorenen Seelen zu retten, aber ich fürchte, viele von ihnen erleiden mittlerweile die gleichen Qualen.\n\nNehmt Euren Mut zusammen und begebt Euch mit meiner Wiege in den Fluss. Ladet alle verlorenen Seelen, die Ihr findet, in die Wiege und schickt sie dann zurück zu mir.", sourceObjective = "Verwendet Thiernax' Rettungswiege, um 12 verlorene Druiden in Gorgoa zu retten und sie zu Thiernax zurückzuschicken.", completion = "Ich danke Euch, {name}. Wir dürfen nicht vergessen, uns gegenseitig zu helfen, während wir tiefer in die Finsternis schreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63971] = { id = 63971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnecken zerstampfen", description = "Passt auf, wo Ihr hintretet. Ihr wollt doch nicht aus Versehen einen Schlundgebundenen zerquetschen, oder?\n\nAber natürlich wollt Ihr das! Es macht nämlich so viel Spaß!\n\n<Lady Mondbeere kichert und zeigt auf die Schnecken um sie herum.>\n\nEs ist so viel einfacher, Schlundgebundene zu zerquetschen, nachdem man sie in stinkende kleine Schnecken verwandelt hat.\n\nHier, nehmt meinen Zauberstab und probiert es mal an ein paar Opfern Eurer Wahl aus.\n\nMöglicherweise muss man sie zuerst ein wenig schwächen, aber es funktioniert bei fast allem!", sourceObjective = "Verwandelt mit Lady Mondbeeres Zauberstab 15 geschwächte Gegner in Schnecken und zerquetscht sie dann.", completion = "<Lord Herne grinst.> Mein Rekord war, vier mit einem Sprung zu zerquetschen.\n\nEiner der vielen Vorteile eines Vierbeiners.", sourceObjectiveStatus = "unverified-source-field" }
quests[63972] = { id = 63972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragt mich nicht, wie man das schreibt", description = "Für Druidengeister wird es da draußen ganz schön gefährlich!\n\nGlücklicherweise haben wir immer Platz für einen weiteren Freund in unserer Gruppe, und diese feine Tirnenn hat angeboten, mir und der Gruppe sicher über das Schlachtfeld zu helfen.\n\n<Die Tirnenn hinter Choofa beginnt langsam zu sprechen, aber Choofa spricht einfach lauter.>\n\nDie gute Kirriprkar... Ich meine, Karripkraker... also, Krackerkrisp...\n\n<Choofa lacht.>\n\nNennen wir sie einfach \"K die Krasse\"!\n\nUnd jetzt alle aufsteigen!", sourceObjective = "Helft Krrprripripkraak und ihren Freunden, Chaos im Tiegel der Verdammten zu verbreiten.", progress = "Krrprripripkraak und Choofa arbeiten als Team zusammen? Das muss ich mir ansehen.", completion = "Ich habe viele Berichte von Jägern erhalten, denen von Krrprripripkraak und ihren Freunden geholfen wurde. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[63973] = { id = 63973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dromaninnendoppel", sourceObjective = "Helft Dromanin Aliothe, die Feinde auf dem Weg zu besiegen und Lord Dretnal zu töten.", completion = "Egal wie stark wir werden, wir sind stärker, wenn wir gemeinsam jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63974] = { id = 63974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wird wehtun", description = "<Niya spricht laut, um das Summen der verschiedenen Nadlernester hinter ihr zu übertönen.>\n\nIch habe Mondbeere schon über zehn Mal dabei erwischt, wie sie diese Nester für ihre Streiche stehlen wollte!\n\nDie anderen Feen haben gesagt, ich sei verrückt, die Nadler hierherzubringen. Zu wild! Zu unberechenbar!\n\nAber genau darum brauchen wir sie ja.\n\nLord Hernes Späher melden mächtige Herolde unter den Truppen unseres Feindes.\n\nNehmt eines dieser Nester und benutzt es, um die Herolde zu überraschen!", sourceObjective = "Verwendet ein aufgewühltes Nadlernest, um Herold Gkeca, Herold Throgtu und Herold Duarri zu schwächen und zu töten.", progress = "Niya erweist sich als ziemlich clevere Strategin...", completion = "Ich wünschte, ich hätte es mit eigenen Augen gesehen!\n\nEin angemessenes Ende für die Herolde...", sourceObjectiveStatus = "unverified-source-field" }
quests[63976] = { id = 63976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'ter Gauner von Oribos", description = "Ah, <Schlundgänger/Schlundgängerin>. Ich habe eine Nachricht.\n\nEine Person möchte Euch einen besonderen Vorschlag unterbreiten. Ich kenne keine Details, aber Ihr sollt sie im hinteren Bereich der Idyllia treffen.", sourceObjective = "Trefft Euch mit der mysteriösen Kontaktperson in Oribos.", completion = "Ist mir ein Vergnügen, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63977] = { id = 63977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insidergeschäfte", description = "Ich bin der führende Experte, wenn es um die Kultur der Mittler geht. Doch die Beziehungen zwischen den Kartellen sind kompliziert und instabil.\n\nKartell So ist hier in Oribos nicht sehr stark vertreten, weshalb die anderen Kartelle vermutlich mehr wissen als ich. Hört Euch einfach mal um: Bei Eurem Ruhm werden sie Euch sicher alle Informationen geben, die uns fehlen.", sourceObjective = "Sprecht mit den verschiedenen Mittlerkartellen in Oribos.", progress = "Hattet Ihr schon Gelegenheit, mit den anderen Kartellen zu sprechen?", completion = "Wie unhöflich. Sie sollten wirklich wissen, mit wem sie sprechen.\n\nIch entschuldige mich für meine Mittlerkollegen, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[63979] = { id = 63979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manches bleibt besser verborgen", description = "Das Oberhaupt des Kartells So stellt eine große Bedrohung für die Schattenlande dar, <Schlundgänger/Schlundgängerin>.\n\nIhr Name ist So'leah. Sie will hier ein Artefakt der Ersten wieder zusammensetzen und seine Macht für ihre selbstsüchtigen Zwecke missbrauchen.\n\nTeile des Relikts liegen angeblich auf Eurer Heimatwelt versteckt. Wir Mittler haben bisher noch niemals einen Weg dorthin gefunden. Aber wenn es So'leah gelingt, schwebt Azeroth ebenfalls in großer Gefahr.\n\nWir müssen sie abfangen.\n\nNicht weit von hier findet Ihr für das Kartell So markierte Fracht. Vielleicht finden wir in der Frachtliste einen Hinweis darauf, wo sich das Oberhaupt des Kartells aufhält.", sourceObjective = "Findet eine Frachtliste von Kartell So.", progress = "Habt Ihr etwas gefunden?", completion = "Tazavesh, der Verhüllte Markt...\n\nEine interessante Ortswahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[63980] = { id = 63980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmugglersuche", description = "Wir Mittler haben erkannt, dass es in unserem besten Interesse ist, wenn wir mobil bleiben. Und diskret.\n\nEine Reihe unserer Städte und Außenposten liegen gut versteckt im Zwischenraum und können einfach von Ort zu Ort reisen.\n\nZu meiner Schande muss ich gestehen, dass ich Tazavesh aus den Augen verloren habe.\n\nUnsere beste Chance ist wohl, das Kartell Ta um Zugang zu bitten. Es rühmt sich, solche Dinge stets im Blick zu haben.\n\nVersuchen wir unser Glück bei den Kartellmitgliedern auf dem Nachtmarkt in Revendreth. Sie sind womöglich etwas kooperativer als ihre Kollegen in Oribos.", sourceObjective = "Sprecht mit Ta'nla dem Identifikator auf dem Nachtmarkt.", completion = "Ihr wollt Informationen?\n\nDas setzt eine Transaktion voraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[63982] = { id = 63982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außerhalb meiner Befugnis", description = "Nun, ich kenne zwar die Lage des Verhüllten Marktes, kann aber in Bezug auf den Transport dorthin wenig für Euch tun.\n\nAls Gegenleistung für Eure Unterstützung bei einer Aufgabe kann ich Euch zu jemandem schicken, der uns beiden helfen könnte. Es gibt da einen Kopfgeldjäger in der Übertragungsstation Ta, einer Enklave der Mittler in der Bastion. Er wird Euch eher weiterhelfen können... und er schuldet mir noch eine Lieferung.\n\nTrefft Euch mit Ta'oku und sagt ihm, dass Ta'nla Euch geschickt hat.\n\nWürdet Ihr gern ein Portal benutzen? Das kann ich arrangieren. Wir sind ja schließlich Geschäftspartner, nicht wahr?", sourceObjective = "Nehmt das Portal zum Nachtmarkt und sprecht mit Ta'oku.", completion = "Gibt es etwas, das ich jagen soll?", sourceObjectiveStatus = "unverified-source-field" }
quests[63983] = { id = 63983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akquise", description = "Ta'nla hat eine sehr... spezielle... Anfrage im Namen eines Klienten.\n\nDie Kyrianer haben an einem neuen Zenturio gearbeitet, den sie \"Aquilon\" nennen. Ich habe einige unserer Handelsspezialisten losgeschickt, um den fraglichen Prototyp zu beschaffen, aber sie sind noch nicht zurück.\n\nSolange ich das Objekt nicht habe, kann ich es natürlich Ta'nla auch nicht liefern. Vielleicht können wir einander helfen.\n\nFindet diesen Aquilon und bringt ihn hierher. Im Gegenzug helfe ich Euch, nach Tazavesh zu kommen.", sourceObjective = "Besorgt den Aquilonprototyp.", progress = "Habt Ihr den... Gegenstand beschafft?", completion = "Perfekt! Damit sind wir wieder im Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[63984] = { id = 63984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen für den Fährmann", description = "Euer Teil der Abmachung ist erledigt, <Schlundgänger/Schlundgängerin>. Kommen wir nun also zu Eurer Bezahlung.\n\nMein Kartell betreibt eine Fähre zwischen Oribos und Tazavesh. Normalerweise wird sie nur zum Frachttransport verwendet, aber wie bei allen Dingen gibt es natürlich auch hier... Ausnahmen.\n\nBringt Ta'meri diese Münze, dann erhaltet Ihr sicheren Zugang zum Markt.\n\nWas dann passiert, obliegt Eurer Verantwortung.\n\n<Ta'oku verbeugt sich und Ihr glaubt, so etwas wie ein leises Lachen zu hören.>", sourceObjective = "Sprecht mit Ta'meri in Oribos.\n\nBereitgestellter Gegenstand:", completion = "Schlundgänger! Was kann Ta'meri für Euch tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[63985] = { id = 63985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verhüllte Markt", description = "Lasst mich raten... Ta'oku hat Euch zu mir geschickt, nicht wahr?\n\n<Ta'meri betrachtet die Münze in Eurer Hand.>\n\nIhr wollt also nach Tazavesh. Nicht gerade das, was wir Fremden üblicherweise anbieten, aber da die Bezahlung bereits erfolgt ist, wäre es mir eine Freude, Euch weiterzuhelfen.\n\nKommt an Bord und vergesst nicht: Während der Fahrt bitte alle Gliedmaßen schön an Bord behalten. Die Strömungen im Zwischenraum sind unberechenbar.", sourceObjective = "Nehmt den Kahn nach Tazavesh.", completion = "Keine Sorge! Ich habe noch einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[63986] = { id = 63986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tazavesh: Jäger des verlorenen Artefakts", description = "Es sieht so aus, als ob Ihr noch einmal zeigen müsst, über welche Kräfte Ihr verfügt, <mein Lieber/meine Liebe>. Die Sicherheitstruppen von Tazavesh werden uns nicht einfach so reinmarschieren lassen.\n\nAber So'leah muss aufgehalten werden. Und wenn es dazu ein wenig körperlicher... Überredungskunst bedarf... dann ist das ein notwendiges Übel.\n\nNehmt ein paar Freunde mit. Ich habe das Gefühl, dass die Sicherheitstruppen hier einige Tricks im Ärmel haben.", sourceObjective = "Betretet Tazavesh und besiegt So'leah.", sourceObjectiveStatus = "unverified-source-field" }
quests[63987] = { id = 63987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ve'lors verlorenes Paket" }
quests[63989] = { id = 63989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charakterschleime", description = "Lehrling! Ich habe nach Euch gesucht.\n\nKevin war ein wundervoller Gehilfe bei unseren Experimenten, daher möchte ich auch meinen anderen Schleimen Assistenzarbeiten antrainieren.\n\nKönnt Ihr Seuchi mitnehmen und testen, inwieweit er organische Lebensformen infizieren kann?", sourceObjective = "Helft Seuchi, seine Infektionsfähigkeit am Zerfleischerausguck zu erproben.", completion = "Wie hat Seuchi sich gemacht? Ist er so ansteckend wie gehofft?", sourceObjectiveStatus = "unverified-source-field" }
quests[63990] = { id = 63990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge in der Nacht", description = "Obwohl meine Suche mühsam war, habe ich zwei vielversprechende Hinweise auf weitere Nachtkrieger finden können. Der erste befindet sich hier in Maldraxxus.\n\nDieser Turm enthält Aufzeichnungen über diejenigen, die in Maldraxxus ankamen. Darunter ist auch jemand, der als \"Die Klinge in der Nacht\" bezeichnet wird. Das sollte also unser nächster Nachtkrieger sein.\n\nAuf dem Weg hierher habe ich eine Menge Fallen entdeckt. Zweifellos werden wir innerhalb des Turms noch mehr davon finden. Jemand versucht, uns aufzuhalten.\n\nWir werden sicherstellen, dass es diesem Jemand nicht gelingt.", sourceObjective = "Sucht im Grabmal des Wissens nach Hinweisen.", completion = "Es ist ja nicht so, als wollte ich Euch nicht helfen, aber... Es gibt Dinge, um die ich mich vorher kümmern muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[63994] = { id = 63994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer ist der Schlundgänger?", description = "Es gibt in Korthia Prophezeiungen über <einen Schlundgänger/eine Schlundgängerin>, <der/die> uns alle vor dem Untergang bewahren kann.\n\nVielleicht ist dieser Tag jetzt gekommen. Vielleicht auch nicht. Ich muss Eure Anima überprüfen. Erst dann weiß ich, ob Ihr die Wahrheit sprecht.\n\nSollte es so sein, ist es meine Pflicht, Eure Anima mit großer Macht zu erfüllen, bevor wir fortfahren.", sourceObjective = "Nehmt an Tal-Galans Schlundgängerprüfung teil.", completion = "Schlundgänger. Wir müssen die anderen rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64006] = { id = 64006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nav Test: Zereth Mortis", description = "Diese Quest folgt einer möglichen Haupthandlung für 9.2. Wir haben über die Haupthandlung von 9.2 noch nicht final entschieden, also ist das nur ein ungefährer Ansatz, wie die POIs eingesetzt werden könnten.\n\nDieser Test unterstützt Bestienmeister und Gottmodus, Ihr könnt also ruhig Cheats verwenden.\n\nNützliche Cheats:\n92BrokerTown - Zurück zum Hub\n92NavTest - Neustart des Nav-Tests (muss erst beendet werden)" }
quests[64007] = { id = 64007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Pakte", description = "Dank all der Mühen, die Ihr und die anderen Helden von Azeroth aufgebracht habt, sind die Pakte gestärkt worden. Doch wir können nicht mehr abwarten, bis der Kerkermeister seinen nächsten Schritt unternimmt.\n\nDer Weg in den Schlund steht offen und unsere Streitkräfte sind bereit.\n\nDie Pakte warten auf Euer Signal, {name}.", sourceObjective = "Ruft die Truppen der Pakte zusammen, um in den Schlund zu ziehen!", completion = "Der Schlund...\n\nNun beginnt die wahre Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
